quests[41805] = { id = 41805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Key of Kalyndras" }
quests[41806] = { id = 41806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jace", description = "Diese kristallisierte Seele sollte den Kommunikator lang genug mit Energie versorgen, um Eure Verbündeten zu erreichen.\n\nAber passt bitte gut auf, {name}. Wenn das Gerät aus den Beständen der Legion stammt, könnte es sein, dass auch seine Erschaffer Eure Nachrichten mithören können.\n\nEure Verbündeten werden sicher schon ungeduldig auf Eure Rückkehr warten.", sourceObjective = "Kehrt zu Jace Düsterweber zurück.", completion = "Hat der Erzmagier uns weiterhelfen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[41807] = { id = 41807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Verbindung herstellen", description = "<Jace wirft einen Blick auf die kristallisierte Seele.>\n\nJa, damit sollte es gehen. Setzt einfach die Energie frei, um den Kommunikator zu aktivieren. Das Gerät sollte schon so voreingestellt sein, dass es gleich mit Allari und ihrer Einheit Kontakt aufnimmt.\n\nWenn Caria da draußen ist, werden wir sie finden und für ihre Sünden büßen lassen.", sourceObjective = "Aktiviert den Legionskommunikator, um einen Bericht von Allari der Seelenfresserin zu erhalten.", progress = "Dies könnte unsere einzige Chance sein, Rache an Caria zu üben. Jeder Moment ist kostbar.", completion = "Nicht gut... Das ist gar nicht gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[41812] = { id = 41812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Boss Cinematic" }
quests[41815] = { id = 41815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluch der Nekrodunklen", description = "Es ist offensichtlich, dass die Alten Götter lange Zeit versucht haben, die Kontrolle über den Hochberg zu übernehmen. Mit ihrer lüsternen Begierde bedrängen sie die Macht dieses Landes und die Stärke der Geister, deren Echos durch diese Gipfel und Täler hallen.\n\nSie werden unseren heiligen Berg nicht bekommen, {name}. Nicht, solange ich noch atme.\n\nZusammen mit den vereinten Hochbergstämmen und Baine Bluthuf an unserer Seite werden wir die Finsternis besiegen... ein für alle Mal.\n\nKommt, lasst uns den Gipfel von den Mächten zurückerobern, die ihn verderben wollen.", sourceObjective = "Reist zum Hochberggipfel.", completion = "Mayla ist mit Ebenhorn vorausgeeilt. Und jetzt wurde sie von uns anderen getrennt.\n\nDas ist nicht gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[41816] = { id = 41816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Oubdob der Knaller" }
