quests[41828] = { id = 41828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Borstenschlund" }
quests[41834] = { id = 41834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masken und Gesichter", description = "Viele Nachtgeborene hatten gehofft, dass Thalyssra die Großmagistrix ihres Amtes entheben würde. Seit sie verschwunden ist, sind die Stimmen der Andersdenkenden verstummt.\n\nWir müssen die Kunde diskret unter der Bevölkerung verbreiten. Ly'leth Lunastre ist dabei die perfekte Verbündete. Sie ist prominent, hat gute Beziehungen und ist der Legion gegenüber nicht freundlich gesinnt.\n\nLy'leth gibt einen Maskenball auf ihrem Anwesen. Dort werden Gerüchte gehandelt wie bare Münze und eingesetzt wie Dolche.\n\nLaden wir uns doch selbst dorthin ein.", sourceObjective = "Sprecht mit 8 maskierten Feiernden, während Ihr Euer Kostüm tragt, und sprecht dann mit Ly'leth Lunastre.", progress = "Sehr erfreut, Eure Bekanntschaft zu machen.", completion = "Die Maske steht Euch.\n\nIn Suramar kann es vorteilhaft sein, eine Zeit lang in die Haut von jemand anderem zu schlüpfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[41836] = { id = 41836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Bodash der Hamsterer" }
quests[41838] = { id = 41838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Schlummer" }
quests[41839] = { id = 41839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entführten", description = "Zusammen mit dem Leichnam von Maylas Vater wurden auch die Leichen von einigen unserer größten Häuptlinge entführt.\n\nDer Graue bereitet in diesem Moment Maylas Vater als Wirtskörper für seine bösen Pläne vor.\n\nDoch die anderen wurden bereits von den Nekrodunklen übernommen. Ihre Leichen tragen jetzt bösartige Drogbargeister in sich.\n\nIch will ehrlich sein: Ich glaube nicht, dass ich mit meinen Fähigkeiten diese Monstrositäten besiegen könnte.\n\nWir brauchen Eure Hilfe!", sourceObjective = "Besiegt die entführten Häuptlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[41840] = { id = 41840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eis und Schatten", description = "Wir haben einen der Nekrodunklen ausschalten können. Ebenhorn hat entdeckt, dass er einen mit Schattenessenz durchtränkten Eissplitter in der Hand hielt.\n\nVielleicht verwenden diese Unholde die Splitter als eine Art Talisman. Ich schlage vor, dass Ihr ihnen diese Schmuckstücke abnehmt.\n\nIch kenne mich mit dieser Art Magie nicht aus, aber Ebenhorn scheint eine Verwendung dafür zu haben.", sourceObjective = "Sammelt 20 Schatteneissplitter.", progress = "Habt Ihr mehr von diesen Splittern finden können?", completion = "Genau zum richtigen Zeitpunkt, {name}. Diese Splitter werden für mein Vorhaben sehr nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[41841] = { id = 41841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Zauberschutz", description = "Die Nekrodunklen bereiten ein Ritual vor, um der Finsternis eine physische Form zu verleihen. Sie haben sich da drinnen verschanzt und uns den Weg versperrt.\n\nMit den Splittern, die Ihr mir gebracht habt, sollten wir die Barriere zerstören können. Wenn das geschehen ist, müssen wir schnell handeln und den letzten Zauberschutz reaktivieren, bevor die Finsternis Gestalt annehmen kann.\n\nGeht entschlossen vor, denn das Schicksal des Hochbergs hängt an einem seidenen Faden.", sourceObjective = "Reaktiviert den Gipfelzauberschutz.", progress = "Das ist die härteste Herausforderung, die ich je bestehen musste.", completion = "Wir haben versagt! Der Zauberschutz ist zerschmettert.\n\nIch spüre, wie sich die Finsternis erhebt...", sourceObjectiveStatus = "unverified-source-field" }
quests[41844] = { id = 41844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Sekhan" }
quests[41849] = { id = 41849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eisenfaust", description = "Es ist Zeit für eine Rettungsmission zur Pforte der Tapferkeit, {name}.\n\nIch werde unsere Truppen vorbereiten und umgehend entsenden. Wir werden eine ansehnliche Armee brauchen, um die riesige Legionsstreitmacht in Sturmheim zu bekämpfen.\n\n<Großmeister/Großmeisterin>, geht Ihr voraus, wann immer Ihr bereit seid. Ich entsende die Truppen, damit sie Euch auf dem Schlachtfeld beistehen.", sourceObjective = "Sprecht mit Angus Eisenfaust in der Kriegsbasis der Wellenskorn in Sturmheim.", completion = "Dann haben sie Euch also zum Großmeister gemacht? Naja, ich war ohnehin beschäftigt!\n\nAuf jeden Fall konnte ich diesen teufelsbesoffenen Dämonendrecksäcken auf der anderen Seite der Straße entkommen, aber unsere Leute sind immer noch in Gefahr.\n\nDiese Legionsmaden wollen die Gefangenen opfern und ihre Seelen verschlingen.\n\nWir müssen ihnen helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41850] = { id = 41850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Meister der Schwerter", description = "Ich habe schlechte Neuigkeiten für Euch: Wir haben keine Zeit, um auf Verstärkung zu warten! Sie opfern genau jetzt die Gefangenen! Jede Minute, die wir hier verschwenden, kostet ein weiteres Leben!\n\nAber alles der Reihe nach: Meine Freundin Sylara wird in dem Lager gleich auf der anderen Seite der Straße gefangen gehalten.\n\nWir müssen sie als Erste befreien, denn sie wird uns eine wertvolle Verbündete sein.\n\nUnd jetzt müssen wir endlich los!", sourceObjective = "Beschafft Dravax' Schlüssel von Dravax und befreit dann Sylara Stahlsang.", progress = "Will einer was auf die Mütze?", completion = "Zum Glück habt Ihr es geschafft. Sylara ist mehr wert als zehn gut ausgebildete Mönche.", sourceObjectiveStatus = "unverified-source-field" }
quests[41851] = { id = 41851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Flut", description = "<Sylara blickt Euch entschlossen in die Augen.>\n\nUnsere Freunde sind in Gefahr. Wir werden sie retten. Tötet alle Legionskrieger, die Euch in die Quere kommen.", sourceObjective = "Tötet 16 Verteidiger der Legion an der Pforte der Tapferkeit.", completion = "<Sylara macht eine tiefe Verbeugung.>\n\nIhr habt gut gekämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[41852] = { id = 41852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Mönch wird zurückgelassen", description = "Die meisten Gefangenen werden im Hauptlager an der Pforte der Tapferkeit gefangen gehalten.\n\nUnsere Leute wurden geschlagen und gefoltert. Und auf sie warten noch schlimmere Dinge, wenn wir sie nicht retten.\n\nFindet die Käfige im Hauptlager und befreit so viele Mönche, wie Ihr nur könnt.\n\nIch werde an Eurer Seite kämpfen und dabei kräftig austeilen!", sourceObjective = "Befreit 6 gefolterte Gefangene.", completion = "Gute Arbeit, Großmeister!\n\nDas dürften alle gewesen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[41853] = { id = 41853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hiroische Rettung", description = "Ich muss Euch um einen Gefallen bitten, {name}. Mein guter Freund Hiro ist immer noch irgendwo da drinnen im Hauptlager.\n\nAber das eigentliche Problem ist, dass sich an der Pforte der Tapferkeit die größten, gefährlichsten und widerwärtigsten Legionskreaturen herumtreiben, die ich je gesehen habe. Wenn wir da einfach reinmarschieren, werden sie uns abschlachten.\n\nAllerdings habe ich gesehen, wie diese Vrykul ein spezielles Gebräu namens Sturmgebräu heruntergestürzt haben. Das ist eine Art Kampftrank, der sie größer und stärker macht.\n\nLasst uns etwas von diesem Getränk stehlen und dann dort hineinstürmen, um Hiro zu retten!", sourceObjective = "Stehlt das Sturmgebräu und rettet dann Hiro.", completion = "Ah, danke, dass Ihr mich gerettet habt. Ich dachte schon, ich würde als Dämonenfutter enden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41854] = { id = 41854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stein um Stein", description = "Die Mönche sind frei und wir haben dieser Eredardame einen herben Rückschlag versetzt.\n\nIch bin wieder bei meinen Freunden und freue mich darauf, heute Nacht in einem Bett zu schlafen.\n\nGehen wir zurück zur Wandernden Insel. Ich habe mich noch nie so gefreut, eine Schildkröte zu sehen.", sourceObjective = "Kehrt zu Eisenkörper Ponshu auf der Wandernden Insel zurück.", completion = "Das sind großartige Neuigkeiten, {name}!\n\nIhr habt nicht nur die Pläne der Legion durchkreuzt, sondern auch zahllose Leben gerettet.\n\nAußerdem habt Ihr drei der besten Mönche gerettet, die wir in jüngster Vergangenheit ausgebildet haben.\n\nDer Orden steht wieder einmal in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[41855] = { id = 41855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schikane!" }
quests[41857] = { id = 41857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Dunkelsteinsklaven" }
quests[41860] = { id = 41860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Händel mit Satyrn" }
quests[41861] = { id = 41861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlund kennenlernen" }
quests[41862] = { id = 41862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur Haustiere können Waldbrände verhindern" }
quests[41863] = { id = 41863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache wird unser sein", description = "Caria befindet sich inmitten des Legionsterritoriums. Sie werden unsere Truppen sofort bemerken, wenn wir einen frontalen Großangriff starten.\n\nDiese Operation darf auf keinen Fall scheitern.\n\nWenn Ihr Euch allerdings allein auf den Weg macht, könnt Ihr Euch womöglich lange genug vor dem Großteil der Legionstruppen verbergen.\n\nUnd denkt daran, {name}: Dies ist keine Rettungsmission. Die Macht der Kriegsklingen der Aldrachi könnte den Krieg zu unseren Gunsten entscheiden. Allari und ihre Männer sind gegebenenfalls ersetzbar.", sourceObjective = "Nehmt Caria Teufelsseele die Kriegsklingen der Aldrachi ab.", completion = "Was ist mit den anderen? Sind sie...?\n\nIch verstehe. Sie haben ihr Leben nicht umsonst geopfert. Die Kriegsklingen werden ganz sicher den Ausgang des Krieges entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41864] = { id = 41864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Kristallinzermalmer" }
