quests[41876] = { id = 41876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umbraxis Tracker" }
quests[41877] = { id = 41877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lady Lunastre", description = "Unsere Freundin Ly'leth hat mich kontaktiert. Sie bittet Euch, sie auf der Großen Promenade zu treffen, von der aus man die Stadt überblicken kann.\n\nHaltet Eure Verkleidung für den Fall der Fälle bereit, {name}.", sourceObjective = "Trefft Euch mit Ly'leth an der Großen Promenade.", completion = "Ich hoffe, Ihr seid bereit, die Stadt zu betreten. Es wird Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[41878] = { id = 41878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gondoliera", description = "Ich brauche Eure Hilfe.\n\nDer Wein, den Ihr so großzügig an die Bedürftigen verteilt habt, war mein letzter Vorrat. Ohne ihn schweben die Leute hier in Gefahr, ihrem Durst zu erliegen und schließlich zu verdorren.\n\nIch bin entschlossen, das so lange wie möglich zu verhindern.\n\nEs gibt eine Frau namens Deline, die mit ihrer Gondel einen kleinen Lieferdienst betreibt.\n\nSucht sie auf, gebt Euch als mein Bote zu erkennen und bietet ihr Eure Hilfe bei der Beschaffung der nächsten Lieferung an.", sourceObjective = "Sprecht mit der Gondoliera.", progress = "Wenn Ihr nicht mitfahren wollt, geht weiter.", completion = "Dann fangen wir mal an.", sourceObjectiveStatus = "unverified-source-field" }
quests[41880] = { id = 41880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhle der Schatten", sourceObjective = "Nehmt Kontakt mit Arluin Schattenklinge auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[41881] = { id = 41881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Heliosus" }
quests[41882] = { id = 41882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüstern in der Finsternis", description = "Bevor wir hierher kamen, haben viele aus unserem Volk versucht, dieser Bedrohung Herr zu werden. Sie wussten nicht, was ihrer harrte.\n\nUnser Volk steht nun im Bann der Alten Götter. Unaufhörlich versuchen sie, uns zu verderben, uns gegeneinander aufzuhetzen.\n\nErweckt meine Brüder und Schwestern aus dieser Betäubung. Befreit sie von den Stimmen, irgendwie.", sourceObjective = "Befreit 6 Beschützer des Hochbergs.", completion = "Gut gemacht, {name}. Wenn man sich nicht absolut im Griff hat, kann das Flüstern selbst die besten Freunde gegeneinander aufhetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41884] = { id = 41884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Geschichten", description = "Geistwandler Ebenhorn ist stabilisiert... zumindest vorerst.\n\nEr hat mir einst von den Zauberschutzen erzählt, die er gegen die Alten Götter aufrechterhalten hat. Er hat sie an Schlüsselpositionen im Gebirge aufgestellt, aber sie vor den Augen der Sterblichen verborgen gehalten, selbst vor meinen.\n\nIn ihrem inaktiven Zustand können die Zauberschutze das Böse nicht aufhalten. Und das ist zweifelsohne auch der Grund für diesen Angriff.\n\nUm die Zauberschutze zu finden, müssen wir uns in die Echos von Ebenhorns Vergangenheit begeben und dort Kontakt mit den Geistern aufnehmen.\n\nWir treffen uns an der Flusswindung, {name}. Dort werden wir mit der Suche beginnen.", sourceObjective = "Trefft Geistwandler Grauhimmel an der Flusswindung.", completion = "Die Geister wissen von vielen Wahrheiten zu berichten, {name}.\n\nWenn wir in ihren Fußstapfen wandeln, können wir vielleicht Ebenhorns Zauberschutze ausfindig machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41885] = { id = 41885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naralex Kneel Seen" }
quests[41886] = { id = 41886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Fiese Ratten!" }
quests[41888] = { id = 41888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Treue der Flamme", description = "Meine Rivalen sind tot und es gibt niemanden in den Feuerlanden, der es wagt, meine Herrschaft infrage zu stellen!\n\nWie versprochen werde ich mich mit den anderen Elementarlords zusammenschließen, um Azeroth zu verteidigen. Die Armeen der Feuerlande werden unzählige Leichen unserer Feinde auf dem versengten Schlachtfeld zurücklassen!\n\nUnd jetzt geht, <Sterblicher/Sterbliche>. Erzählt Eurem Irdenen Ring, dass der Feuerlord höchstpersönlich Euch zur Seite steht!", sourceObjective = "Sprecht mit Scharfseher Nobundo im Herz von Azeroth.", completion = "Ich hätte nicht gedacht, dass ich den Tag erleben würde, an dem unsere vier großen Elementarlords sich mit den sterblichen Völkern von Azeroth verbünden.\n\nIhr habt etwas erreicht, was noch keinem Scharfseher in der Geschichte des Irdenen Rings gelungen ist.\n\nHeute ist wahrlich ein Tag, an den sich noch viele Generationen erinnern werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[41889] = { id = 41889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebel der Vergangenheit", description = "Lasst uns die Sache angehen und diese Reittierrüstung herstellen, ja?", sourceObjective = "Stellt einen Steinbalglederharnisch her.", progress = "Ich bin sehr gespannt, was dabei rauskommt.", completion = "Gibt es irgendetwas, das wir nicht können? Allmählich glaube ich, dass das nicht der Fall ist!\n\nIch werde sicherstellen, dass Mei dieses Pferdegeschirr erhält. Behaltet das Muster, und vielleicht könnt Ihr damit einen kleinen Profit erzielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41890] = { id = 41890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dunkle Seite des Mondes", description = "Xavius ist hier vorbeigekommen, doch sein Ziel ist nicht ganz klar. Der Alptraum vernebelt mir die Sinne!\n\nDiese Flüchtlinge haben von einem uralten Mondbrunnen gesprochen, der in den Ruinen vor uns verborgen liegt.\n\nWenn er der Verderbnis widerstehen konnte, wird er mir die nötige Konzentration verleihen. Bei Elunes Licht, wir werden meinen Gatten finden.\n\nSucht mich sofort am Mondbrunnen auf, {class}.", sourceObjective = "Beschützt Tyrande, während sie am uralten Mondbrunnen ihre Wache hält.", completion = "Er lebt noch, aber alles Weitere müssen wir erst in Erfahrung bringen. Beten wir um Euretwillen, dass er unverletzt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[41893] = { id = 41893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderbnis überlassen", description = "Dürfte ich Euch um einen letzten Gefallen bitten? Varethos, ein sehr alter Freund von mir, ist den Qualen des Alptraums zum Opfer gefallen. Wir haben einst zusammen dieses Land beschützt. Seine enge Verbundenheit mit ebendiesem ist ihm jetzt zum Verhängnis geworden.\n\nWie bei den anderen Opfern gibt es auch für ihn keine Hoffnung mehr.\n\nIch bitte Euch, {name}, sorgt dafür, dass er Frieden findet.", sourceObjective = "Tötet Hüter Varethos.", completion = "Mein Blick verschwimmt, doch ich freue mich, dass er Ruhe gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[41895] = { id = 41895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Haustiere" }
quests[41896] = { id = 41896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Operation: Murlocfreiheit" }
quests[41897] = { id = 41897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan der Meisterin", description = "Der Schattenhammer diente immer demselben Zweck. Er will das Ende der Welt erzwingen. Seine diesbezüglichen Pläne ändern sich, aber seine grausame Absicht bleibt immer gleich.\n\nDer Schattenhammer lässt sich nicht allein über den Kampf bezwingen. Um ihn zu besiegen, müssen wir seine schändlichen Pläne aufdecken und sie ein für alle Mal durchkreuzen.\n\nLasst uns zuerst das Lager nach Hinweisen darauf durchsuchen, was seine wahren Absichten hier sein könnten.", sourceObjective = "Sammelt Auszüge aus dem Tagebuch der Meisterin ein.", progress = "Welchen schändlichen Plan hat der Schattenhammer dieses Mal ausgeheckt, um die Welt zu vernichten?", completion = "Wenn wir die Meisterin nicht aufhalten können, wird der Schattenhammer über genug Macht verfügen, um Tiefenheim zu erobern und die Elemente zu versklaven!\n\nDas dürfen wir auf keinen Fall zulassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41898] = { id = 41898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselung der Elemente", description = "Laut des Tagebuchs der Meisterin hat der Schattenhammer eine Methode entdeckt, wie man die Leere verwenden kann, um selbst die mächtigsten Elementare zu unterjochen.\n\nIm Tagebuch wird ausdrücklich erwähnt, dass die Kinder von Therazane als Testsubjekte dienen. Ich weiß nicht, ob die Meisterin dies wortwörtlich oder im übertragenen Sinne meinte. Auf jeden Fall müssen wir diese Elementare befreien und die finsteren Rituale unterbinden.\n\nAugenscheinlich führt uns diese Reise noch tiefer in die Finsternis...", sourceObjective = "Befreit die Diener von Therazane aus den Zwielichttiefen.", progress = "Wir dürfen nicht zulassen, dass solch finstere Rituale abgehalten werden.", completion = "Die Diener von Therazane sind frei und die dunklen Beschwörungsrituale haben ein Ende... vorerst.", sourceObjectiveStatus = "unverified-source-field" }
quests[41899] = { id = 41899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangen gehalten!", description = "Der Schattenhammer hat hier Gefangene versklavt, <Scharfseher/Scharfseherin> {name}.\n\nIn den Tiefen der Mine lassen die Kultisten die Gefangenen sich zu Tode schuften.\n\nEine solche grausame Misshandlung werde ich nicht dulden! Lasst uns den Weg durch die Mine freikämpfen und alle Gefangenen des Schattenhammers befreien, damit sie nach Hause zu ihren Familien zurückkehren können.\n\nDer Schattenhammer wird für seine Verbrechen büßen!", sourceObjective = "Rettet 10 Schattenhammersklaven aus den Zwielichttiefen.", completion = "Die Gefangenen sind frei, aber es gibt noch so viel mehr zu tun, wenn wir dem Schattenhammerkult ein Ende setzen wollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[41900] = { id = 41900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Versprechen der Erde", description = "Tiefenheim dankt Euch, <Schamane/Schamanin>.\n\nDer Schattenhammer hat schon immer die Herrschaft über mein Königreich angestrebt, aber diese letzte Bedrohung war viel größer als seine bisherigen Bemühungen.\n\nFür Eure Dienste um die Elemente der Erde verspreche ich, meine Armeen dem Irdenen Ring zur Verteidigung Azeroths zur Verfügung zu stellen.\n\nIch habe nichts für die sterblichen Völker übrig, aber es steht der Brennenden Legion nicht zu, diese Welt zu zerstören.\n\nTeilt Eurem Irdenen Ring mit, dass Therazane, die Steinmutter, an seiner Seite steht!", sourceObjective = "Sprecht mit Berater Sevel im Herz von Azeroth.", completion = "Es ist schön, Euch wohlbehalten wiederzusehen, Scharfseher. Mit der Zusicherung von Therazane haben wir jetzt drei der Elementarlords in unserer Sache vereint.\n\nAber einer bleibt noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[41901] = { id = 41901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eid des Windlords", description = "Habt Dank, <Sterblicher/Sterbliche>, für meine Wiedergeburt. Doch Dank allein wäre nicht ehrenhaft.\n\nIch weiß, der Irdene Ring möchte Azeroth vor der Brennenden Legion retten.\n\nIch stelle mein Schwert und die Armeen des Himmelswalls zur Verfügung, um Azeroth zu helfen.\n\nWenn es an der Zeit ist zu kämpfen und der Irdene Ring der Brennenden Legion auf dem Schlachtfeld gegenübersteht, wird der Windlord an Eurer Seite sein.", sourceObjective = "Sprecht mit Berater Sevel.", completion = "Der Windlord hat versprochen, dem Irdenen Ring im Krieg gegen die Brennende Legion zu helfen?\n\nDas sind in der Tat gute Nachrichten!\n\nLeider bleibt nur wenig Zeit zum Feiern, es muss noch so vieles erreicht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[41905] = { id = 41905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht aus dem Tiankloster", description = "Wir haben Meldung von allen Tempeln von Pandaria erhalten – bis auf einen.\n\nWir haben mit einem Vogel eine Nachricht zum Tiankloster geschickt, aber bisher keine Antwort erhalten. Die Stille ist ziemlich ungewöhnlich.\n\n<Großmeister/Großmeisterin>, ich schlage vor, dass wir umgehend unseren Champion Chen Sturmbräu losschicken, um die Lage zu sondieren.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Untersuchung des Tianklosters\" ab.", completion = "Euer Champion hat sich beeilt, {name}! Laut diesem Bericht wird das Tiankloster angegriffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[41907] = { id = 41907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereitstellung", description = "Ich bin gekommen, um dem Orden des Verheerten Tempels meine Hilfe anzubieten.\n\nMeine Aufgabe ist es, eine solide Grundlage für die Operationen hier zu schaffen. Im Moment haben wir Verwundete zu versorgen und Mäuler zu stopfen. Danach können wir uns über unsere Verteidigung den Kopf zerbrechen.\n\nLao Shu ist verantwortlich für unsere Vorräte hier. Geht und sprecht jetzt mit ihm im Gasthaus.", sourceObjective = "Sprecht mit Lao Shu im Gasthaus 'Der Lachende Kranich'.", completion = "Ah, ja ja ja! Der Hohe Älteste Wolkensturz hat gut daran getan, Euch zu mir zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[41909] = { id = 41909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Wellenskorn nach", description = "Wir haben Späher ausgesandt, die nach unseren entführten Verbündeten suchen sollen und unsere Bemühungen sind wahrscheinlich endlich von Erfolg gekrönt.\n\nMan hat sie nach Sturmheim, der Heimat der Vrykul, verfolgt, doch das unbekannte Gebiet hat unser Vorankommen verlangsamt und jetzt laufen wir Gefahr, die Spur zu verlieren.\n\nIch schlage vor, dass wir unsere Champions umgehend losschicken, damit sie bei der Spurensuche helfen.", sourceObjective = "Benutzt die Späherkarte und schließt die Missionen \"Den Wellenskorn nach\" ab.", completion = "Ausgezeichnet. Es wird zwar extrem gefährlich, die Pforte zu infiltrieren, aber dank dieser Informationen kennen wir zumindest den genauen Standort und die Truppenstärke des Feindes.", sourceObjectiveStatus = "unverified-source-field" }
quests[41910] = { id = 41910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freyas Quelle", description = "Als Erstes benötigen wir Wasser von Freyas Quelle.\n\nEinmal im Jahr, am ersten Tag der Sonnenwende, steht die Sonne am schneebedeckten Gipfel des höchsten Punkts des Hochbergs. Der Schnee schmilzt, läuft durch eine Klamm und sammelt sich in einem kristallklaren See.\n\nMan behauptet, sein Wasser verleiht ewige Jugend. Törichte Märchen, wenn Ihr mich fragt, aber wir werden dieses seltene, reine Wasser für unser Getränk brauchen.\n\nMein Vorschlag wäre, unsere Champions loszuschicken, damit sie Proben für uns holen, denn Eure Fähigkeiten sind anderweitig gefragt.", sourceObjective = "Benutzt die Späherkarte und schließt fünf Missionen \"Freyas Quelle\" ab.", completion = "Dieses Wasser wird jeden Winter nur aus dem frischsten Neuschnee gefiltert und ist ein wichtiger Bestandteil unseres Getränks!", sourceObjectiveStatus = "unverified-source-field" }
quests[41911] = { id = 41911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergänglichkeitshopfen", description = "Der Hopfen für unser Getränk ist ein ganz besonderer und es wird schwierig werden, ihn zu beschaffen.\n\nUnvergänglichkeitshopfen wächst nur in dem Reich, das als Smaragdgrüner Traum bekannt ist. Das bedeutet, dass wir diese Zutat nur von einem Druiden bekommen können.\n\nEs gibt eine Lieferantin, von der ich ihn erhalte, aber sie möchte wahrscheinlich etwas im Austausch dafür haben.", sourceObjective = "Sprecht mit Fleuris Asternblatt in Val'sharah und tauscht 20 Stücke Steinbalgleder für 1 Beutel Unvergänglichkeitshopfen ein.", completion = "Mhmmm, riecht nur... dieser Hopfen! Der wird einfach großartig, da bin ich ganz sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[41914] = { id = 41914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Katakomben räumen" }
quests[41915] = { id = 41915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vermächtnis des Meisters", description = "Ihr arbeitet für einen mörderischen Dieb.\n\nDas Design, das er haben will? Es heißt Magistrixschliff und wurde von meinem Ehemann perfektioniert. Dieser Schuft Lespin hat ihn für sein Geheimnis ermordet.\n\nIch ließ ihn in einer kleinen Höhle im Norden der Stadt bestatten, weil wir nicht nach Tel'anor reisen konnten. Mit ihm gemeinsam begraben ist der Foliant, in dem die Geheimnisse des Designs zu finden sind.\n\nHolt das Design und passt auf, dass es ihm nicht in die Hände fällt!", sourceObjective = "Untersucht das Grab des Juwelenschleifers.", progress = "Wo ist der Meister?", completion = "Sieh mal einer an, scheint so, als ob der alte Narr endlich seinen Meister gefunden hat.\n\nEs sieht so aus, als ob die Promenade einen neuen Juwelier braucht, und ich glaube, ich habe von meinem früheren Meister so viel gelernt, wie ich konnte.\n\nHier ist etwas für Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41916] = { id = 41916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Zukunft", description = "Wir müssen uns beeilen, {name}. Ich muss so viele meiner Leute wie möglich retten, bevor der Angriff beginnt.\n\nEs hat sich bei den Leuten in der Stadt herumgesprochen, dass es bei uns sicher ist, und einige von ihnen fürchten sich nicht mehr vor dem Exil.\n\nBegebt Euch zur Großen Promenade, Champion. Findet jene, die sich uns anschließen wollen, und lasst sie wissen, dass die Zeit für die Flucht gekommen ist.", sourceObjective = "Rettet 8 Aufrührer der Shal'dorei auf der Großen Promenade.", completion = "Während unsere Stärke zunimmt, werden unsere Feinde immer schwächer. Wir werden diesen Kampf gewinnen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[41917] = { id = 41917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Bear Cub" }
quests[41918] = { id = 41918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Träumers", description = "Erzdruide Großhuf sollte über den Erfolg der Mission unterrichtet werden, aber ich muss Euch leider bitten, allein zurückzukehren.\n\nIch kann es einfach nicht hinnehmen, dass Lord Ursoc von Xavius gefangen genommen wurde. Schon allein der Gedanke daran lässt mich fast die Beherrschung verlieren! Ich werde herausfinden, wo er ist! Und wenn ich dafür ganz Azeroth absuchen muss!\n\nAber Ihr könnt gewiss sein, dass sich unsere Wege wieder kreuzen werden, {name}.", sourceObjective = "Kehrt zu Erzdruide Großhuf im Hain der Träume zurück. Ihr könnt 'Traumwanderung' benutzen, um über den Smaragdgrünen Traumpfad zu reisen.", completion = "Dann steckt Xavius also dahinter. Tausend Tode sind nicht Strafe genug für diesen Schändling!\n\nAber Ihr habt immerhin die Klauen zurückgebracht. Dies wäre nicht einmal mir selbst gelungen.\n\nIhr seid wahrhaftig genau der Held, die wir für den Kampf gegen die Legion brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41919] = { id = 41919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schatten erhellen", description = "Die Reißzähne des Verschlingers sind im Besitz von Akaari Schattenblut, einer von Kil'jaedens persönlichen Assassinen. Wann immer wir versucht haben, sie umzubringen, war sie schon vor unserem Eintreffen verschwunden.\n\n<Valeera kritzelt ein paar Zeilen auf ein Stück Papier und gibt es Euch dann.>\n\nAber dieses Mal nicht. Wir arbeiten mit diesen Kontakten zusammen, um Akaari zu finden und ihr endlich die Reißzähne abzunehmen.\n\nSucht jeden einzelnen dieser Kontakte auf und begrüßt sie mit den Worten \"Die Schatten erhellen\". Hört Euch an, was sie zu berichten haben.", sourceObjective = "Sprecht mit Euren Kontaktleuten in Dalaran, um Informationen über Akaari Schattenbluts Aufenthaltsort zu erhalten.", completion = "<Valeera wirft Euch einen Blick zu.>\n\nGlück gehabt?", sourceObjectiveStatus = "unverified-source-field" }
quests[41920] = { id = 41920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Raffinesse", description = "Eine Rune der Portale?! Was glaubt Val'zuun, wer er ist?\n\n<Valeera atmet einmal tief durch.>\n\nEs ist wohl die Sache wert, aber diese Runen findet man nicht so leicht. Es sei denn...\n\nErzmagierin Celindra, die Portalmeisterin der Kirin Tor, unterhält ein Studienzimmer in der Stadtmitte. Wir Schurken sind dort nicht besonders willkommen, und sie würde uns auch nicht einfach eine Rune geben, selbst wenn wir sie...\n\n<Valeera grinst.>\n\nAber von fragen hat auch niemand geredet.", sourceObjective = "Borgt eine Rune der Portale von Erzmagierin Celindra aus.", progress = "Man sagt, die Reißzähne des Verschlingers würden ihresgleichen suchen. Wenn dem so ist, dann sind sie jeden Preis wert.", completion = "Val'zuun hat tatsächlich Wort gehalten... Ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[41921] = { id = 41921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Pelle rücken", description = "Der \"Zauberkasten\" ist nicht weit von hier entfernt. Wir haben ein paar Agenten in der Nähe stationiert, die den Bereich sichern können.\n\nMacht Euch auf alles gefasst: Akaari wird sich nicht kampflos ergeben.", sourceObjective = "Stellt Akaari Schattenblut im Zauberkasten.", progress = "Ich glaube es nicht...", completion = "Es war wieder nur eine List?!", sourceObjectiveStatus = "unverified-source-field" }
quests[41922] = { id = 41922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter!", description = "Dieser lügende DÄMONENABSCHAUM! Ich hätte es besser wissen sollen.\n\nJetzt werden wir Val'zuun zeigen, was es heißt, sich mit den Ungekrönten anzulegen.", sourceObjective = "Schließt Euch Valeera Sanguinar im Schattenabstieg an.", completion = "Er lügt wieder einmal, ich weiß es... aber er könnte unsere einzige Chance sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[41924] = { id = 41924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißzähne des Verschlingers", description = "Wenn Ihr mich verschont, kann ich mit Eurer Rune der Portale ein Tor zu Akaaris Festung im Wirbelnden Nether öffnen.\n\nNatürlich ist es nicht gerade einfach, die Meisterassassine der Legion auf ihrem eigenen Terrain zu töten, aber die Reißzähne des Verschlingers sind doch sicher einen Versuch wert, oder?\n\n<Val'zuun lächelt.>\n\nIch werde Euch den Weg durch die Festung zeigen, wenn Ihr angekommen seid, aber Akaari müsst Ihr allein besiegen.", sourceObjective = "Nehmt Akaari Schattenblut die Reißzähne des Verschlingers ab.", progress = "Hattet Ihr Erfolg?", completion = "Ich wusste, dass Ihr es schaffen würdet, {name}. Ich bin froh, Euch an unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41925] = { id = 41925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hel erleuchtet" }
quests[41926] = { id = 41926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückkehrender Champion" }
quests[41927] = { id = 41927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Runenwaldsterben" }
quests[41929] = { id = 41929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tutorial Lockbox Looted" }
quests[41930] = { id = 41930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heldenmut gefragt" }
quests[41931] = { id = 41931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Manadurst" }
quests[41934] = { id = 41934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Verdammnis", description = "Ich benötige ein Symbol für meine Herrschaft als Feuerlord. Eine Waffe, die jeden das Fürchten lehrt, der es wagen sollte, sich mir entgegenzustellen!\n\nTief im Bau der Aschenweber gibt es einen uralten Speer, der aus dem Herzen der Feuerlande stammt. Glutnarbe ist eine lebendige Waffe, deren üble Macht das Verständnis Sterblicher weit übersteigt.\n\nBeweist Eure Stärke und eignet Euch Glutnarbe in meinem Namen an! Wenn Ihr es überlebt, werde ich Euren schwächlichen Völkern vielleicht im Kampf gegen die Brennende Legion beistehen.", sourceObjective = "Holt Euch Glutnarbe, die Fackel der Verdammnis.", progress = "Die Fackel der Verdammnis wird mir gehören!", completion = "Wie ich sehe, habt Ihr Glutnarbe erfolgreich erweckt. Und der Speer wurde gut genährt.\n\nVielleicht seid Ihr doch stärker, als ich zunächst angenommen hatte...", sourceObjectiveStatus = "unverified-source-field" }
quests[41935] = { id = 41935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angespannte Lage" }
quests[41936] = { id = 41936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wurdet herausgefordert!" }
quests[41937] = { id = 41937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining" }
