quests[41944] = { id = 41944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarruns Leiter" }
quests[41945] = { id = 41945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tianji, von der Schule des Ochsen", description = "Seid gegrüßt, <Großmeister/Großmeisterin>. Neben mir seht Ihr die Späherkarte. Mit ihrer Hilfe könnt Ihr unsere Verbündeten auf wichtige Missionen im Gebiet der Verheerten Inseln schicken.\n\nDiese erste Aufgabe ist von entscheidender Bedeutung. Tianji, eine berühmte Ausbilderin der Kampfkunst im Ochsenstil, war zu den Verheerten Inseln unterwegs, als sie angegriffen wurde.\n\nWir sollten Chen Sturmbräu entsenden, um ihr zu helfen. Er ist für diese Aufgabe wie geschaffen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Tianji braucht Hilfe\" ab.", progress = "Wie verläuft die Mission?", completion = "Ausgezeichnet, Großmeister! Die Mission war ein Erfolg. Unsere neue Lehrerin, Rekrutiererin Tianji, macht sich gerade an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[41946] = { id = 41946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau der Truppen", description = "Unseren Champions ist es gelungen, uns die Dienste der für ihren Ochsenstil berühmten Rekrutiererin Tianji zu sichern.\n\nMit ihren anerkannten Braumeistertechniken ist sie eine wertvolle Ergänzung für unseren Tempel. Sie hat bereits begonnen, ein paar neue Schüler auszubilden.\n\nSprecht am besten gleich mit ihr und bildet einen Ochseninitianden aus.", sourceObjective = "Sprecht mit Rekrutiererin Tianji und bildet einen Ochseninitianden aus.", completion = "Ausgezeichnet. Diese Trupps werden bei der Verteidigung der Verheerten Inseln unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[41948] = { id = 41948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Streichelzoo im Himmel" }
quests[41949] = { id = 41949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der Drekirjar" }
quests[41950] = { id = 41950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Donner des Schmerzes", description = "Ihr habt Euch als <würdiger Verbündeter/würdige Verbündete> der Thorignir erwiesen. Wir werden Euch unsere Stärke verleihen. Zuvor habe ich allerdings noch ein Anliegen an unseren neuen Champion.\n\nDer Drache, der Euch zu mir geführt hat, wartet nur darauf, blutige Rache an den Vrykul zu üben. Ich möchte, dass Ihr diesen Drekirjar gemeinsam zeigt, was es bedeutet, den Zorn der Thorignir zu wecken. Ihre Schuld muss mit Blut bezahlt werden.\n\nSprecht mit Vethir, wenn Ihr bereit seid.", sourceObjective = "Fliegt mit Vethir und tötet 150 Verbündete des Gottkönigs in Hrydshal.", sourceObjectiveStatus = "unverified-source-field" }
quests[41953] = { id = 41953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vis'ileth" }
quests[41955] = { id = 41955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutlinie des Steins" }
quests[41956] = { id = 41956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteinerte Akolythen" }
quests[41957] = { id = 41957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bitte des Verteidigers", description = "Ich habe ein Hilfegesuch von Verteidiger Boros in Dalaran erhalten.\n\nEr versorgt einen Soldaten, dem es gelungen ist, der Legion zu entkommen! Der Soldat wurde verwundet und bis jetzt half kein bekanntes Heilmittel gegen seine Verletzungen. Normalerweise wäre das ein Fall für einen Akolythen, aber der Soldat sprach im Delirium von T'uure! Ich dachte, das heilige Juwel wäre verloren gegangen!\n\nIhr verfügt über die Stärke des Lichts. Vielleicht könnt Ihr ihm ja helfen?\n\nWenn Ihr möchtet, kann Bruder Larry einen Flug nach Dalaran für Euch arrangieren.", sourceObjective = "Trefft Euch mit Verteidiger Boros vor der \"Helfenden Hand\" in Dalaran.", completion = "Danke, dass Ihr so schnell hierhergekommen seid, Bruder.", sourceObjectiveStatus = "unverified-source-field" }
quests[41958] = { id = 41958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Ominitron" }
quests[41961] = { id = 41961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehrtsachen", description = "In der Kiste, unter verschiedenem Krimskrams verborgen, befindet sich ein Signet mit einem unverwechselbaren Wappen.\n\nDer Ring aus einem silbrigen, unzerbrechlichen Metall scheint im Laufe der Zeit abgenutzt worden zu sein, als hätte ihn sein Besitzer immer wieder geistesabwesend durch die Finger gleiten lassen.", sourceObjective = "Bringt das Signet des Wächters zu Jarod Schattensang.", sourceObjectiveStatus = "unverified-source-field" }
quests[41963] = { id = 41963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knowledge Unlock Daily Tracking Quest" }
quests[41964] = { id = 41964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergiftetes Wasser" }
quests[41965] = { id = 41965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondschwingenbefreiung" }
quests[41966] = { id = 41966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hausbesuch", description = "Nach der Tragödie an der Verheerten Küste dachte ich, dass Barrem es nicht schaffen würde. Beim Licht, wir haben dort schon viel zu viele gute Soldaten wie ihn verloren.\n\nIch konnte kaum glauben, dass er noch lebte, als eine unserer Patrouillen ihn hierherbrachte. Sie haben ihn aus dem Meer gefischt und er war mit Wunden übersät, die jeden gewöhnlichen Draenei umgebracht hätten.\n\nIrgendetwas stimmt aber nicht mit diesen Wunden, denn all unsere Heilungsversuche zeigen überhaupt keine Wirkung. {class}, ich bitte Euch als <Bruder/Schwester> des Lichts, alles zu tun, um ihn zu retten.", sourceObjective = "Versorgt die Wunden von Beschützer Barrem.", completion = "Ich... Ich verdanke Euch mein Leben, Bruder. Aber ich kann Euch ansehen, dass Ihr wegen etwas anderem hier seid.\n\n<Ihr erzählt Barrem, dass er T'uure in seinen Fieberträumen erwähnt hat.>\n\nIch muss von Alora geträumt haben... Sie war meine Zellengenossin in dieser verfluchten Dämonenwelt, in die ich verschleppt wurde. Sie erzählte mir, dass sie den Kristall gesehen hätte, aber sonst nichts weiter.\n\nIch hoffe, sie ist noch am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[41967] = { id = 41967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus der Dunkelheit", description = "Alora und ich konnten durch eines der Legionsportale zurück nach Azeroth entkommen, aber dann verließ uns das Glück.\n\nDurch das Portal gelangten wir auf eine kleine Insel irgendwo westlich der Verheerten Küste. Sie hatten uns schnell ausfindig gemacht und wir rannten in Richtung des Wassers, um dort Schutz zu suchen. Als ich mich mit einem Sprung in Sicherheit bringen wollte, wurde ich verwundet. Aber Alora geriet ins Stolpern... und ich sah, wie sie sie zurückschleppten.\n\nBitte rettet sie! Ich werde das Lager auf Eurer Karte eintragen. Lasst nicht zu, dass sie diese Leiden erneut durchmachen muss!", sourceObjective = "Reist zur Dunkelsteininsel nahe der Verheerten Küste und sucht nach Alora.", completion = "Ich konnte spüren, wie mir die Seele aus dem Körper gerissen wurde. Wenn Ihr nicht gekommen wärt... Ich will gar nicht daran denken!\n\nGibt es etwas, dass ich vielleicht für Euch tun kann? Immerhin verdanke ich Euch mein Leben.\n\n<Ihr erzählt ihr von Barrem.>\n\nDann ist Barrem also auch noch am Leben? Oh, dem Licht sei Dank! Ja, ich werde Euch gern alles erzählen, was ich weiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[41980] = { id = 41980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempelverteidigung" }
quests[41981] = { id = 41981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stürmischer Beistand", description = "{name}, wenn Ihr nichts dagegen habt, würde ich Euch gern auf Eurer Reise über den Himmelswall begleiten.\n\nEs gibt hier Wunder, die ich mit eigenen Augen sehen möchte, und es wäre mir eine große Ehre, an Eurer Seite zu reisen.\n\nEs wird nicht einfach sein, den mächtigen Donneraan wiederzubeleben und die vier großen Elementarlords zu vereinen.\n\nGeht Ihr voran, <Scharfseher/Scharfseherin>. Ich werde folgen.", sourceObjective = "Eskortiert Scharfseher Nobundo über den Vortexgipfel.", sourceObjectiveStatus = "unverified-source-field" }
quests[41982] = { id = 41982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book Read Tracking Quest" }
quests[41984] = { id = 41984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kriechenden Nebel" }
quests[41986] = { id = 41986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[41987] = { id = 41987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garn" }
quests[41989] = { id = 41989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut meines Blutes", description = "Wie <mein lieber Bruder/meine liebe Schwester> gerade demonstriert hat, hat Elisandes Entscheidung, den Schild zu deaktivieren, für Unruhe unter den Nachtgeborenen gesorgt.\n\nLoyalisten und Dämonen marschieren Seite an Seite durch die Straßen. Furcht und Misstrauen nehmen unsere Herzen in Besitz. Familien bekämpfen einander.\n\nIch werde Thalyssra helfen, eine neue Rebellion zu entfachen, aber zuvor müssen wir uns um Anarys kümmern.\n\nIch möchte nicht, dass das Blut meines Blutes vergossen wird, nur um <ihn/sie> zur Vernunft zu bringen.\n\nIhr findet Anarys wahrscheinlich am Denkmal unseres Vaters. Bringt <ihn/sie> zu mir, und zwar lebendig.", sourceObjective = "Besiegt Anarys Lunastre und liefert <ihn/sie> Ly'leth Lunastre lebend aus.", progress = "Anarys könnte unsere Pläne von vornherein gefährden.", completion = "Ich danke Euch. Jetzt können wir uns an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[41990] = { id = 41990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerhackt" }
quests[41992] = { id = 41992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Asche" }
quests[41993] = { id = 41993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung von ganz oben", description = "Ich hatte Decksdienst auf dem Luftschiff, das auf dem Weg zur Verheerten Küste abgestürzt ist. Ich muss wohl ohnmächtig geworden sein, denn ich bin durch eine Art Schlag wieder aufgeweckt worden. Ich befand mich auf einem Atoll und über mir stand ein Man'ari mit einem Stab aus dunklem Kristall. Ich bin mir ganz sicher, dass dieser Stab T'uure war!\n\nMein ganzes Leben lang habe ich Geschichten über T'uure und seine heilenden Kräfte des Lichts gehört. Irgendwie müssen die Man'ari den Kristall verdunkelt haben. Wir müssen ihn zurückholen und wieder in seinen ursprünglichen Zustand bringen!", sourceObjective = "Etwas Unerwartetes hat Eure Diskussion unterbrochen, kümmert Euch darum!", completion = "Ihr sucht einen Dämon mit einem Stab aus Kristall? Nun, es gibt da eine Eredar, die sich selbst Lady Calindris nennt und perfekt auf Eure Beschreibung passt.\n\nAber hinter der bin ICH schon her! Ich habe bereits ihren Diener über die gesamten Inseln gejagt und werde mir diese Gelegenheit nicht entgehen lassen.\n\nAber ich könnte dennoch etwas Unterstützung gebrauchen. Wenn Ihr mir helft, würde ich Euch diesen Stab überlassen. Ihre Ausrüstung ist mir egal, denn ich will nur ihre Seele.\n\nAlso, was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[41995] = { id = 41995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Verderbnis" }
quests[41996] = { id = 41996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verworrener Alptraum" }
quests[42000] = { id = 42000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Wahrheit", description = "Ihr kennt vielleicht schon Orik Treuherz hier. Seit dem Nordendfeldzug widmet er seine gesamte Zeit den Nachforschungen über Tyr.\n\nOrik hat Beweise für einen mächtigen Schild, den Tyr vor langer Zeit geschaffen hat. Mit der Hilfe der Sonnenläufer könnten wir ihn vielleicht endlich finden.\n\nSprecht bitte gleich mit ihm.", sourceObjective = "Sprecht mit Orik Treuherz in Dalaran.", progress = "Freut mich, dass Ihr dabei seid. Vor uns liegt eine lange Reise.", completion = "Freut mich, dass Ihr mitkommt. Ich wollte mich schon eine ganze Weile damit beschäftigen. Mit der Hilfe der Seher können wir es meiner Ansicht nach schaffen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42001] = { id = 42001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aluneth, Großstab der Magna", description = "Aluneth... eine mächtige, gefährliche Waffe. Wenn man den Legenden Glauben schenken darf, ist Aluneth der Name eines sehr alten und äußerst mächtigen Arkanwesens, das auf irgendeine Art mit uralter Magie an einen Stab gebunden wurde.\n\nAls Aegwynn Aluneth vor vielen Jahren freigab, wurde er den Kirin Tor anvertraut. Diese fürchteten sich vor seiner ungezügelten Macht und übergaben ihn dem blauen Drachenschwarm, der ihn an einem geheimen Ort aufbewahren sollte. Nur der Schwarm weiß genau, wohin er gebracht wurde.\n\nDer Drache Kalec stellt vermutlich unsere beste Chance dar. Er gehört inzwischen dem Rat der Sechs an.", sourceObjective = "Trefft Kalec in der Violetten Zitadelle in Dalaran.", completion = "Ihr sucht nach Aluneth? Eine wirklich gefährliche Waffe.\n\nVor langer Zeit überließen die Kirin Tor ihn dem blauen Drachenschwarm. Diese verwahrten ihn an dem einzigen Ort, der seine ungezügelte Macht halten konnte: in der Nexuskammer.\n\nIch war allerdings schon lange nicht mehr dort. Nachdem der blaue Drachenschwarm sich aufgelöst hatte, wurde der Nexus so gut wie aufgegeben. Wir können nicht herausfinden, ob die Nexuskammer noch intakt ist... oder was einen im Nexus selbst erwarten könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[42002] = { id = 42002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Nordend", description = "Ich habe natürlich schon etwas Vorbereitungsarbeit erledigt. Ich glaube, dieser Gorvold wurde am Schildhügel im Heulenden Fjord bestattet.\n\nTahu kann dabei helfen, sein Grab zu finden, und mithilfe eines kurzen Rituals sollten wir unsere Antworten erhalten!\n\nTrefft uns am Schildhügel im Heulenden Fjord und wir gehen zum nächsten Schritt über.", sourceObjective = "Trefft Orik Treuherz auf dem Schildhügel im Heulenden Fjord.", completion = "Ich hoffe, die Reise war weder zu lang noch zu anstrengend.\n\nDann wollen wir mal unseren toten Abenteurer suchen, einverstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[42004] = { id = 42004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterschiff" }
quests[42005] = { id = 42005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Sage", description = "Ihr solltet selbst mal die Sage lesen. Sie liegt dort drüben.\n\nWir sind hier, um mit dem Geist des Vrykul zu sprechen, von dem ich gesprochen habe. Der mächtige Seher Tahu Weisenwind sollte in der Lage sein, seinen Geist zurückzubringen. Aber wir müssen ihn dazu bringen, mit uns zu kommunizieren.\n\nSprecht mit Tahu, damit wir anfangen können.", sourceObjective = "Lasst Euch das Ende der Geschichte vom Geist des Sagenhelden erzählen.", completion = "Ich glaube, ich habe bereits eine Spur zu der Insel. In der Taverne war ein mächtiger Krieger, der auf einer Insel in Sturmheim ins Grab eines Vrykulkönigs eingedrungen ist.\n\nDas muss die sein, nach der wir suchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42006] = { id = 42006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Bedrohung", description = "Wenn Ihr den Nexus sucht, seid vorsichtig. In Kaltarra gehen seltsame Dinge vor und es wäre sinnvoll, diese zu verstehen, bevor Ihr weitermacht.\n\nWährend meines letzten Besuchs der Drachenöde spürte ich ungewöhnliche Energien vom Azurdrachenschrein ausgehen. Da dieser Ort ein wesentlicher Bestandteil von Malygos' Plänen während des Nexuskriegs war, könnte das, was sich dort befindet, den derzeitigen Zustand des Nexus erklären.\n\nNehmt diesen Abbildkristall. Ich muss in Dalaran bleiben und mich Angelegenheiten der Kirin Tor widmen, aber wir können uns mit seiner Hilfe unterhalten. Viel Glück.", sourceObjective = "Sucht am Azurdrachenschrein nach Hinweisen zum derzeitigen Zustand des Nexus.", progress = "Das Kommunikationsgerät ist inaktiv.", completion = "Dies ist offenbar ein Kommunikationsmittel, das häufig von den Astralen genutzt wurde.\n\nMöglicherweise könnt Ihr damit herausfinden, was hinter den Ereignissen am Drachenschrein steckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42007] = { id = 42007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vergessener Feind", description = "Das Gerät summt noch immer vor Energie. Es muss vor Kurzem benutzt worden sein.\n\nEs wird wohl mit dem Schalter in der Nähe aktiviert.", sourceObjective = "Aktiviert das Kommunikationsgerät der Astralen am Azurdrachenschrein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42008] = { id = 42008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augen des Drachen", description = "Ihr solltet Euch gleich nach Kaltarra in der Boreanischen Tundra begeben, {name}. Ich empfehle, dass Ihr dort ein paar bedeutende Orte auskundschaftet und mich entsprechend informiert.\n\nIch kenne das Gebiet gut und sollte Euch anleiten können.\n\nBeeilt Euch!", sourceObjective = "Erkundet die wichtigen Orte in Kaltarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[42009] = { id = 42009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigung des Arkanen", description = "Die Energie von Aluneth peitscht aus dem Inneren der geschwächten Nexuskammer heraus. Vielleicht gelingt es uns, diese rohe, chaotische Energie für unsere Zwecke zu nutzen.\n\nWenn wir die Energie in die Sognadeln speisen können, sollte dies zu einer recht... zerstörerischen Reaktion führen.", sourceObjective = "Ermächtigt Euch mit instabiler Arkanenergie, indem Ihr arkane Anomalien besiegt oder sie aus austretender arkaner Energie entlang des Nexusfundaments bezieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42010] = { id = 42010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselte Arkanenergie", description = "Ihr verfügt über die notwendige Macht, um die Sognadeln zu vernichten.\n\nBei den Rissen, an denen die Sognadeln im Boden stecken, gibt es große Ansammlungen von Leerenenergie. Konzentriert die Macht von Aluneth auf diese Stellen. Die Reaktion sollte zur Überladung führen und die darüberliegenden Sognadeln vernichten.\n\nIhr müsst schnell handeln. Das Astraleum wird sicher nicht untätig zusehen, während Ihr ihren Machenschaften ein Ende setzt.", sourceObjective = "Nutzt Eure gesammelte instabile Arkanenergie, um die Sognadeln in Kaltarra zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42011] = { id = 42011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nexuskammer", description = "Wenn das Astraleum es geschafft hat, Azuregos gefangen zu nehmen, ist es noch mächtiger, als ich befürchtet hatte.\n\nAzuregos und ich waren zwar nicht immer einer Meinung, aber wir sind Brüder. Da Ihr den Astralen ein Ende setzen und Aluneth an Euch bringen wollt, möchte ich Euch bitten, darüber hinaus auch meinen Bruder aus ihren Klauen zu befreien.\n\nJetzt, da die Sognadeln vernichtet sind, hat der Schild sich aufgelöst. Der Nexus wartet, {name}.", sourceObjective = "Besiegt Nexusprinz Bilaal und beansprucht Aluneth, Großstab der Magna, für Euch.", completion = "Ich danke Euch für Azuregos' Rettung, {name}. In dem Wissen, dass der Nexus von ihm behütet wird, kann ich nun Ruhe finden.\n\nWas Euch angeht, so seid Ihr immer für eine Überraschung gut. In all meiner Zeit habe ich keinen {class} gesehen, der die chaotischen Energien von Aluneth kontrollieren konnte.\n\nDanke für alles, was Ihr für mich und meinesgleichen heute getan habt. Ihr seid wahrlich der Held, der uns in den Kampf gegen die Legion führen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[42013] = { id = 42013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Höllenschlund" }
quests[42014] = { id = 42014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verderbter Jahrgang" }
quests[42015] = { id = 42015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fäden des Schicksals" }
quests[42017] = { id = 42017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schrein des Wahrheitshüters", description = "Wir fliegen auf direktem Wege zur Insel. Mein Freund sagte, dass der Krieger, der vor uns hier war, nie den Schrein selbst betreten hat, da sie auf der Suche nach einem bestimmten Grab waren.\n\nWenn ein Vrykulheld den Schrein nicht betreten konnte, wette ich, dass er immer noch durch Tyrs Macht geschützt ist. Ich glaube, dass die Chancen für uns recht gut stehen.\n\nMein Kumpel Cato wird uns dort treffen. Möglicherweise müssen wir auf die Künste eines guten Heilers zurückgreifen!", sourceObjective = "Geht zur Schildruhinsel in Sturmheim und beansprucht den Wahrheitshüter für Euch.", completion = "Es ermutigt mich, dass Eure Suche von Erfolg gekrönt war, {name}. Wir haben Eure Rückkehr erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[42018] = { id = 42018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht zu retten" }
quests[42019] = { id = 42019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut gegen Schuppen" }
