quests[42027] = { id = 42027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faronaar im Chaos" }
quests[42028] = { id = 42028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Alptraum" }
quests[42031] = { id = 42031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übles Wachstum", description = "Naralex hat Euch gebeten, zu ihm zu kommen. Er ist bereit, die Probe zu analysieren, die er von Shaladrassil zurückgebracht hat.", sourceObjective = "Trefft Euch mit Naralex, pflanzt den Peitschersamen ein und analysiert die Effekte.", progress = "So etwas habe ich noch nie gesehen...", completion = "Ihr kommt gerade von Naralex? Was habt Ihr aus der Probe lernen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[42032] = { id = 42032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proben des Alptraums", description = "Es gibt noch vieles, das wir über den Alptraum nicht wissen.\n\nBevor wir ihn bekämpfen können, müssen wir begreifen, wie er sich verbreitet.\n\nLasst uns unsere Champions zu den Wurzeln von Shaladrassil in Val'sharah schicken, um sie einige Proben holen zu lassen, die wir untersuchen können.", sourceObjective = "Schließt die Mission \"Proben des Alptraums\" ab.", completion = "Unsere Champions sind soeben von Shaladrassil zurückgekehrt, Erzdruide. Die Reise war ein großer Erfolg!", sourceObjectiveStatus = "unverified-source-field" }
quests[42033] = { id = 42033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malornes Zuflucht", description = "Ich verstehe... Es ist so, wie wir immer gefürchtet hatten. Der Smaragdgrüne Alptraum hat unsere Welt gefunden.\n\nWir müssen den uralten Gott Malorne anrufen.\n\nReist nach Südosten zum Schrein von Malornes Zuflucht. Dort halten wir Druiden seit Tausenden von Jahren ein heiliges Relikt versteckt, ein Geschenk des weißen Hirsches selbst.\n\nIch habe bereits Broll Bärenfell vorausgeschickt, um Euch anzukündigen.", sourceObjective = "Sprecht mit Broll Bärenfell bei Malornes Zuflucht in Val'sharah.", completion = "Ich bin sehr froh, dass Ihr da seid, {name}, aber wir hätten uns schon früher hier einfinden sollen! Als ich hier ankam, herrschte hier das Chaos.\n\nDie Überlebenden haben gesagt, sie seien von Satyrn angegriffen worden, aber wie kann das sein? In diesen Wäldern ist schon seit Ewigkeiten kein Satyr mehr gesehen worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42034] = { id = 42034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umklammerung des Alptraums", description = "Die meisten Druiden konnten entkommen, aber sie sagen, dass sich immer noch unzählige Feinde am Schrein aufhalten würden.\n\nDie Anführerin des Schreins, Sylendra Hainsang, ist zurückgeblieben, um Malornes Götzen zu verteidigen. Wir müssen ihr zu Hilfe eilen.", sourceObjective = "Tötet 5 Räuber der Schattenteufel, rettet Sylendra Hainsang und untersucht den Altar von Malorne.", completion = "So dreist oder so mächtig waren die Satyrn noch nie. Sie haben uns komplett überrascht und unsere Magie konnte nichts gegen ihre Angriffe ausrichten. Ohne Euch hätte ich das hier nicht überlebt.\n\nUnd jetzt muss ich unbedingt den Götzen retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42035] = { id = 42035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind verfolgen", description = "Auch wenn der Götze gestohlen wurde, gibt es vielleicht noch Hoffnung.\n\nAls ich im Schrein gefangen war, habe ich gesehen, wie sich die räuberischen Satyrn mit ihm davongemacht haben. Ihre Spur ist sicher noch ganz frisch.\n\nMit unseren geschärften Sinnen sollten wir sie ausfindig machen können.\n\nWir müssen ihrer Spur durch den Wald folgen und den Götzen zurückholen!", sourceObjective = "Verwendet Eure Katzengestalt, um der Satyrspur zu folgen.", completion = "Na, seht an, was wir hier haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[42036] = { id = 42036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götze der Wildnis", description = "Diesem hier konnten wir ein Geständnis abringen. Wir wissen jetzt, dass ihr Anführer den Götzen in das Mondklauental verschleppt hat, aber nicht, wo genau er ihn versteckt.\n\nEiner der Satyrn wird sicherlich wissen, wohin genau er gebracht wurde.\n\nBringt diese Satyrn dazu, Euch Genaueres zu verraten... und wenn es das Letzte ist, was sie tun.", sourceObjective = "Greift 6 Satyrn der Schattenteufel an, um von ihnen Informationen über den Götzen der Wildnis zu erhalten.", progress = "Habt Ihr den Götzen der Wildnis geborgen?", completion = "Der Götze... Welch Erleichterung, ihn in Euren Händen zu sehen, {name}.\n\nWir werden ihn hier im Hain der Träume sicher aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[42037] = { id = 42037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammlung der Traumweber", description = "Nachdem Ihr den Götzen der Wildnis bergen konntet, wird es jetzt Zeit, dass wir Kontakt mit Malorne aufnehmen. Allerdings wird dieses Ritual die vereinte Kraft vieler Druiden in Anspruch nehmen.\n\nEntsendet Eure Champions, um den Druiden unseres Ordens mitzuteilen, dass wir uns bei Nordrassil versammeln werden. Wir alle werden uns daran beteiligen müssen.", sourceObjective = "Sammelt Druiden, indem Ihr Missionen der Reihe \"Versammlung der Traumweber\" abschließt.", completion = "Sehr gut, die Druiden haben sich versammelt. Im Augenblick sollten sie sich bei Nordrassil einfinden, um sich auf das Ritual vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42038] = { id = 42038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Broll Bärenfell", sourceObjective = "Ich habe genug vom Alptraum gesehen, um zu wissen, dass er keine leere Drohung darstellt. In seinen Fängen werden sogar die Stärksten zu Feinden ihrer selbst.\n\nIhr habt allerdings Mut und Seelenstärke auch im Angesicht dieser großen Gefahr bewiesen. Ich vertraue vollkommen darauf, dass Ihr uns gegen unseren Feind zum Sieg führen werdet.\n\n{name}, ich möchte Euch meine Loyalität zusichern und stelle mich in Eure Dienste und die Eures Druidenordens.", sourceObjectiveStatus = "unverified-source-field" }
quests[42039] = { id = 42039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sylendra Hainsang", sourceObjective = "{name}, ich schulde Euch mein Leben. Durch Eure Taten habe ich eine zweite Chance erhalten, und ich habe nicht die Absicht, diese Chance zu vergeuden.\n\nMit Eurer Hilfe konnten wir den Götzen der Wildnis zurückholen. Es wäre ein entsetzlicher Verlust gewesen, wenn solch ein heiliges Relikt in die falschen Hände gefallen wäre.\n\nJetzt werde ich diese Reise bis an ihr Ende gehen.\n\nLasst mich für Euch kämpfen. Wenn jemand den Alptraum besiegen kann, dann seid in meinen Augen Ihr derjenige.", sourceObjectiveStatus = "unverified-source-field" }
quests[42040] = { id = 42040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg zu Nordrassil", description = "Jetzt ist die Zeit für uns gekommen, den Götzen der Wildnis zu verwenden und mit Malorne in Kontakt zu treten.\n\nFür das Ritual benötigen wir eine große Menge Energie. Aus diesem Grund werden wir bei Nordrassil zusammenkommen und die Essenz des Weltenbaums anzapfen.\n\nWir dürfen keine Zeit verschwenden. Der schnellste Weg führt über den Smaragdgrünen Traumpfad. Geht Ihr voran, wir werden folgen.", sourceObjective = "Sprecht mit Erzdruide Hamuul Runentotem auf dem Smaragdgrünen Traumpfad.", completion = "Irgendetwas stimmt hier nicht, {name}. Das ist nicht der Traum. Ist es möglich, dass Xavius' Kreaturen in unsere Zuflucht eingedrungen sind? Wie konnten sie die Zauberschutze überwinden?", sourceObjectiveStatus = "unverified-source-field" }
quests[42041] = { id = 42041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Alptraum durchstehen", description = "Wir werden hier angegriffen, {name}!\n\nDie Alptraumkreaturen brechen in diesem Moment in den Traumpfad ein.\n\nVernichtet sie. Sie dürfen sich hier nicht länger aufhalten, denn sonst wird der Alptraum auch hier Wurzeln schlagen!", sourceObjective = "Tötet 12 Alptraummonstrositäten.", completion = "Gut, ich spüre schon, wie der Einfluss des Alptraums nachlässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42042] = { id = 42042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klitzekleine Kleinigkeiten!", description = "Oh, {name}, ich bin ja so froh, Euch zu sehen!\n\nDie Tiere des Waldes flüsterten von Problemen auf dem Traumpfad, also bin ich sofort gekommen!\n\nHier im Smaragdgrünen Traum leben doch so viele klitzekleine Wesen, die jetzt ganz allein und verloren sind!\n\nKönntet Ihr nicht losziehen und sie einsammeln? Ihr könnt meine Flöte verwenden, um sie anzulocken.\n\nIch danke Euch vielmals, <tapferer Druide/tapfere Druidin>!", sourceObjective = "Verwendet Mylunes Flöte, um 15 klitzekleine Feendrachen einzusammeln.", completion = "Ja, jetzt sind sie gerettet! Ich danke Euch vielmals!", sourceObjectiveStatus = "unverified-source-field" }
quests[42043] = { id = 42043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumen", description = "Während sich der Alptraum ausbreitet, verschlingt er die Lebenskraft von allem, womit er in Berührung kommt.\n\nJe weiter er sich ausbreitet, desto schwächer wird unsere Magie.\n\nZu Beginn, wenn die Verderbnis noch nicht so tief eingesickert ist, können wir die betroffenen Gebiete noch davon befreien.\n\nIch werde Euch Elunes Segen gewähren. Wenn Ihr ihre Kraft kanalisiert, könnt Ihr die Ausbreitung des Alptraums rückgängig machen.", sourceObjective = "Läutert 100 Alptraumkriecher.", completion = "Ausgezeichnete Arbeit, {name}. Ich wusste, dass Ihr es mithilfe von Elunes Macht schaffen würdet, die Verderbnis des Alptraums zu läutern. Ihr Segen ist eine mächtige Waffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[42044] = { id = 42044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein sterbender Traum", description = "Tief im Herzen des Sumpfes lebt Kaltherz, ein Urtumbeschützer des Traumpfades.\n\nEr war einer der ersten, die sich dem Alptraum entgegengestellt haben, aber er ist vollständig der Verderbnis erlegen.\n\nEs tut mir unendlich leid, aber wir müssen ihn vernichten.", sourceObjective = "Tötet Kaltherz.", progress = "Niemand ist vor dem Alptraum gefeit.", completion = "Heute trauere ich um einen gefallenen Verbündeten, der seit Äonen in diesen Wäldern zu Hause war.\n\nIn dem Wissen, dass er sein Leben zum Schutz dieses heiligen Ortes gab, kann er jetzt in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42045] = { id = 42045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwiesprache mit Malorne", description = "Unsere Arbeit hier ist erledigt, {name}. Wir haben den Traumpfad erfolgreich verteidigt. Jetzt ist es nur noch eine Frage der Zeit, bis er sich vollständig erholt haben wird.\n\nAber es gibt noch dringendere Angelegenheiten.\n\nBringt jetzt den Götzen der Wildnis zu Nordrassil. Mit etwas Glück haben sich schon alle dort eingefunden. Wir werden uns dort wiedertreffen.", sourceObjective = "Sprecht mit Remulos bei Nordrassil.", progress = "Ich bin froh, Euch zu sehen, {name}.", completion = "Mein Großvater Malorne, der uralte Gott der Wildnis selbst... Ich habe so lange auf diesen Tag gewartet, nur um jetzt feststellen zu müssen, dass er in großer Gefahr schwebt.\n\nWenn selbst er im Alptraum gefangen ist, wie können wir dann noch Hoffnung hegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42046] = { id = 42046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Wenn selbst Malorne in Gefahr ist, stehen die Dinge noch schlimmer als befürchtet. Jetzt kommt es allein auf uns an.\n\nWir haben nicht mehr viel Zeit. Wir müssen sofort im Hain der Träume zusammenkommen.", sourceObjective = "Trefft Erzdruide Rensar Großhuf im Hain der Träume in Val'sharah.", completion = "Vielen Dank für all Eure heldenhaften Taten, großer {class}. Ohne Eure Hilfe hätten wir den Götzen niemals zurückbekommen und hätten somit auch nicht mit Malorne in Kontakt treten können.\n\nNun da wir wissen, dass er im Alptraum gefangen ist, können wir einen Plan ausarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42047] = { id = 42047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hamuul Runentotem", sourceObjective = "Solange ich denken kann, habe ich der Wildnis gedient, junge Druiden ausgebildet und mitangesehen, wie sie an Wissen und Erfahrung gewannen.\n\nEs gibt nur wenige, die in den Rang des Erzdruiden aufgestiegen sind, aber ich glaube, Ihr habt das Zeug, zu einem unserer Besten zu werden.\n\nEs wäre mir eine Ehre, Euch als Anführer des Hains zu folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42048] = { id = 42048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Mylune", sourceObjective = "Oh, hallo {name}! Meine Freunde aus dem Wald wollten gar nicht mehr aufhören, von Euch zu reden, nachdem Ihr fortgegangen seid, und sie haben mich davon überzeugt, Euch hier aufzusuchen!\n\nEdle Druiden mit Eurem Mut und Eurer Güte findet man nicht alle Tage.\n\nDas wird bestimmt TOTAL viel Spaß machen, meint Ihr nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[42049] = { id = 42049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie für das Portal", description = "Wenn Malorne im Alptraum gefangen ist, müssen wir versuchen, ihn zu retten. Es klingt wie ein aussichtsloses Unterfangen, aber wir können nicht tatenlos zusehen.\n\nAuf dem Smaragdgrünen Traumpfad gibt es ein verlassenes Portal, das wir Druiden vor langer Zeit geschlossen haben, weil es zum Riss von Aln führt.\n\nUm es erneut mit Energie zu versorgen, benötigen wir Alptraumsplitter, die sich bei den Satyrleutnants finden lassen.\n\nSendet unsere Champions aus, um Jagd auf diese Feinde zu machen.", sourceObjective = "Sammelt 10 Alptraumsplitter auf Missionen der Reihe \"Energie für das Portal\".", progress = "Wie viele Splitter haben wir gesammelt?", completion = "Ausgezeichnet. Diese Splitter bersten fast vor negativer Energie. Seid vorsichtig damit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42050] = { id = 42050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger des Traums", description = "Noch nie sah sich unser Orden mit einer solch großen Herausforderung konfrontiert. Um sie zu bestehen, müssen wir uns alle gegenseitig unterstützen.\n\nAllerdings können wir nur wenige Verteidiger für die kommende Schlacht abstellen.\n\nBroll, Sylendra, Zen'tabra und Mylune haben freiwillig angeboten, Euch hinunter in das Tal zu begleiten. Ich kann aber nur einen von ihnen entbehren.\n\nWer von ihnen soll Euch im Kampf unterstützen?", sourceObjective = "Wählt einen Verbündeten.", progress = "Habt Ihr eine Wahl getroffen?", completion = "Eine gute Wahl. Die anderen werden mir bei der Verteidigung hier helfen. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42051] = { id = 42051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinein in den Alptraum", description = "Das Portal in den Alptraum ist bereit, {name}. Remulos und die anderen sind bereits vorausgegangen.\n\nNiemand weiß, was für Schrecken auf der anderen Seite warten, {name}. Viel Glück.", sourceObjective = "Durchschreitet das Alptraumportal auf dem Smaragdgrünen Traumpfad.", completion = "Lasst Euch nicht täuschen, {name}. Was man für die Gipfel des Hyjal halten könnte, ist tatsächlich eine von unseren Feinden geschaffene Illusion.\n\nSie ist eine Nachbildung des dunkelsten Alptraums in Malornes Geist. Das ist der Krieg der Ahnen, eine Schlacht, die sich vor Tausenden von Jahren zugetragen hat.\n\nIn diesem Krieg wurde Azeroth zum ersten Mal von der Brennenden Legion bedroht, und damals wurden auch Malorne und die Wilden Götter besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42053] = { id = 42053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg der Ahnen", description = "Um Malorne zu befreien, müssen wir den Krieg der Ahnen gewinnen. Vor Tausenden von Jahren haben die größten Verteidiger unserer Welt Seite an Seite in dieser Schlacht gekämpft. Um jetzt zu siegen, müssen wir es genauso machen.\n\nBegebt Euch auf das Schlachtfeld, besiegt die Streitkräfte der Legion, rettet unsere Verbündeten, belebt sie wieder und schützt alle Unschuldigen, die zwischen die Fronten geraten sind. Jeder besiegte Feind und jeder gerettete Verbündete zählt, um unsere Siegchancen in diesem Krieg zu erhöhen!", sourceObjective = "Gewinnt den Krieg der Ahnen.", completion = "Heute führt Ihr uns zum Sieg, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42054] = { id = 42054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archimonde der Entweiher", description = "Wir haben die Schlacht zu unseren Gunsten gewendet, {name}! Die Brennende Legion wurde erheblich geschwächt.\n\nJetzt verbleibt nur noch eine Aufgabe. Malorne ist in den Kampf mit Archimonde verwickelt, dem Dämon, der ihn vor zehntausend Jahren tötete.\n\nDenkt daran, {name}, wir sind in Malornes Alptraum gefangen. Es ist unmöglich vorherzusagen, was uns noch erwartet, aber wir MÜSSEN etwas unternehmen.\n\nMöge Elune uns den Weg weisen, {name}.", sourceObjective = "Besiegt Archimonde.", completion = "<Malorne starrt Euch direkt an. Seinem Körper entströmt eine beruhigende Energie. Sofort verspürt Ihr ein umfassendes Gefühl von Frieden, Ruhe und Dankbarkeit.>", sourceObjectiveStatus = "unverified-source-field" }
quests[42055] = { id = 42055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr des Halbgottes", description = "<Malornes Stimme dringt in Euren Geist ein.>\n\nIhr möget vielleicht sterblich sein, aber Eure Tapferkeit ist jener der alten Götter ebenbürtig.\n\nIch spüre, dass Ihr vom pulsierenden und wilden Geist der Natur beseelt seid. In Euch wirkt die Essenz der Natur selbst: der WILLE zu überleben.\n\nVon unserem heutigen Triumph wird man noch viele Jahrhunderte erzählen, {name}.\n\nKehrt durch dieses Portal zurück in die Welt der Wachenden. Wir sprechen uns wieder, wenn wir zurück im Hain der Träume sind.", sourceObjective = "Empfangt Malornes Segen.", completion = "{name}, wir Ältesten des Hains der Träume haben uns besprochen und sind uns einig. Wir möchten, dass Ihr den Hain der Träume anführt.\n\nSo verleihen wir Euch am heutigen Tage den Titel Erzdruide des Hains der Träume, eine der größten Ehrungen unseres Ordens.\n\nDamit lastet auf Euch nun auch die Verantwortung unseres Ordens: der Schutz der Wildnis! Möget Ihr uns gut leiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42056] = { id = 42056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Remulos", sourceObjective = "Wir haben schon einen langen Weg zusammen zurückgelegt, {name}. Und all Eure Entscheidungen auf diesem Weg haben den Hain der Träume zum Sieg geführt.\n\nIch würde mein Leben dafür geben, Azeroth zu verteidigen, und ich weiß, dass dies auch für Euch gilt.\n\nAuf uns warten große Gefahren, darum hört mich an, {name}: Wir müssen die Natur um jeden Preis schützen!", sourceObjectiveStatus = "unverified-source-field" }
quests[42061] = { id = 42061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge Trigger Hit" }
quests[42062] = { id = 42062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfnacht: Klitzeklitzekleiner" }
quests[42063] = { id = 42063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kommt nicht auf die Größe an" }
quests[42064] = { id = 42064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist Illid... Moment mal..." }
quests[42065] = { id = 42065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenmeisterin", description = "Jetzt bleibt nur noch eine Sache zu tun, <Scharfseher/Scharfseherin> {name}. Wir müssen uns dem Kampf mit der Anführerin des Schattenhammers stellen und ihrem dunklen Plan ein für alle Mal ein Ende bereiten.\n\nOhne ihre sogenannte Meisterin werden die verbleibenden Kultisten gezwungen sein, sich aus Tiefenheim zurückzuziehen.\n\nErst wenn der Schattenhammer zerschlagen und Tiefenheim gerettet ist, werden wir Therazanes Unterstützung im Kampf gegen die Dämonen der Brennenden Legion erhalten.", sourceObjective = "Besiegt die Herrin des Zwielichts.", completion = "Dann war die Herrin des Zwielichts in Wahrheit also ein Drache... Und ich dachte, Sintharias Brut wäre vollständig ausgerottet worden.\n\nIch frage mich, ob Zeryxia vielleicht gar nicht die Letzte ihrer Art war...", sourceObjectiveStatus = "unverified-source-field" }
quests[42067] = { id = 42067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großes Maul und nichts dahinter" }
quests[42068] = { id = 42068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr der Schatten", description = "Der Schattenhammer ist wieder aufgetaucht. Sie bauen eine Armee auf, um mein Königreich zu erobern. Eine geradezu wahnwitzige Idee ihrerseits, die ich dennoch ernst nehmen muss.\n\nIch kann den sterblichen Völkern keine Hilfe anbieten, solange Tiefenheim bedroht ist. Wenn Ihr also die Elementarlords auf Eurer Seite wissen wollt, müsst Ihr Euch zuvor beweisen.\n\nZieht los, deckt den Plan des Schattenhammers auf und bereitet ihm ein Ende!", sourceObjective = "Sprecht mit Muln Erdenwut in Tiefenheim.", completion = "Gut, dass Ihr da seid, Scharfseher {name}. Der Schattenhammer hat eine beachtliche Stellung hier in Tiefenheim errichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[42069] = { id = 42069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felbats" }
quests[42070] = { id = 42070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Turm der Wächterinnen: Die Sternenjägerwacht" }
quests[42071] = { id = 42071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Ehren der Vergangenheit" }
quests[42072] = { id = 42072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boros Tracker" }
quests[42073] = { id = 42073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boros Tracker Two" }
quests[42074] = { id = 42074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr des Lichts", description = "Ausgezeichnet!\n\nEin wenig weiter diesen Pfad hinunter gibt es ein Tor. Und wie die meisten Konstrukte der Legion bezieht auch dieses seine Energie aus Seelen.\n\nIch glaube, der Tod des Inquisitors würde gerade genug Energie freisetzen, um es zu aktivieren und einen Durchgang an seinen Ursprungsort zu öffnen.\n\nFinden wir also heraus, wo uns dieser Pfad hinführt!", sourceObjective = "Begleitet Jace Düsterweber durch das Portal und holt Euch T'uure, das Fanal der Naaru.", completion = "Es ist T'uure! Ich dachte, er wäre uns auf ewig verloren gegangen!\n\nAls ich diesen Stab das letzte Mal sah, flohen wir von einer kleinen Welt namens Niskara. Die Legion brach unvermittelt über uns herein, und wir konnten nur dank einiger tapferer Verteidiger fliehen, die mit T'uure zurückblieben, um uns Zeit zu verschaffen.\n\nIch hätte nicht gedacht, dass es machbar wäre, doch Ihr wart in der Lage, T'uure wiederzufinden. Ihr wandelt wahrlich im Licht, {name}. Ihr habt meinen Respekt und meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[42075] = { id = 42075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanischer Rückschlag" }
quests[42076] = { id = 42076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattenmoordorf" }
quests[42077] = { id = 42077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wandelnde Alpträume" }
quests[42078] = { id = 42078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Seal" }
quests[42079] = { id = 42079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maskerade", description = "Dank meinem Vater genießt meine Familie großes Ansehen in dieser Stadt. Mithilfe meines Netzwerks an Kontakten können wir Suramar und seine Bürger auf Thalyssras Rückkehr vorbereiten.\n\nIhr müsst einer der Nachtgeborenen werden. Ihr müsst das Vertrauen unserer Freunde wie auch unserer Feinde gewinnen.\n\nIhr müsst zu jemand anderem werden.\n\n<Ly'leth übergibt Euch eine glänzende Festmaske.>\n\nSetzt dies hier Anarys auf.", sourceObjective = "Setzt Anarys Lunastre die Maske des Spiegelbilds auf.", progress = "Keine Sorge. Das wird ihm nicht wehtun.", completion = "Mein kleiner Bruder wird jetzt ein neues Kapitel aufschlagen, ob es ihm gefällt oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[42080] = { id = 42080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastion Bradenbach" }
quests[42081] = { id = 42081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit dem Neuen", description = "Nun, hier ist Euer neuer Katalysator. Versucht dieses Mal, ihn nicht zu zerstören. Ich habe wirklich keine Lust, noch einen herzustellen.\n\nAch, und sagt Eurem Auftraggeber Deucus, dass er mir jetzt wirklich etwas schuldig ist.", sourceObjective = "Bringt den neu geschmiedeten leistungsstarken Sudkatalysator zu Deucus in Dalaran.", completion = "Ihr seid fertig? Lasst mal sehen!\n\n<Deucus nimmt Euch den Katalysator ab und platziert ihn an der Wand.>\n\nDas nenne ich einen gut aussehenden Sudkatalysator. Ich bin froh, dass ich ihn im Vergleich mit dem alten Plunder, den ich vorher hatte, etwas aufgewertet habe.\n\nEigentlich hat Svena mir sogar einen Gefallen getan, indem sie den alten zerstört hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[42082] = { id = 42082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Epizentrum" }
quests[42083] = { id = 42083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Fragile Notice - Phase Controller" }
