quests[42087] = { id = 42087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grüner Schrecken" }
quests[42088] = { id = 42088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierung der Schneemähnen", description = "Es hört einfach nicht auf!\n\nJetzt berichten mir meine Späher, dass einige Drogbar sich an unserer Flanke vorbeigeschlichen haben und das Dorf der Schneemähnen angreifen.\n\nGeht und helft bei der Evakuierung. Wir werden hier standhalten und versuchen, Euch mehr Zeit zu verschaffen.", sourceObjective = "Evakuiert Rotschopf Himmelshaar, Tarvim Tageswandler und den Alten Nefu.", progress = "Ich wusste, wir hätten dieses Dorf besser absichern müssen.", completion = "Gerade rechtzeitig. Unsere Späher berichten, dass der Unterkönig selbst gekommen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[42089] = { id = 42089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefallenen" }
quests[42090] = { id = 42090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huschende Versuchsobjekte" }
quests[42096] = { id = 42096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Naralex", sourceObjective = "Ich beobachte schon seit einiger Zeit, wie Ihr die Ränge durchlaufen habt, {name}. Mit Euch als Anführer ist unser Orden in guten Händen.\n\nZählt mich zu Euren Champions, Erzdruide.", sourceObjectiveStatus = "unverified-source-field" }
quests[42097] = { id = 42097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchsuchung des Archivs", description = "Das Archiv der Schwarzen Ernte birgt unermessliches magisches Wissen, das im Lauf der Zeit aus verschiedenen Quellen zusammengetragen wurde.\n\nMan kann davon ausgehen, dass wir unter den unzähligen Schriftrollen etwas finden werden, das uns bei der Rettung der verbleibenden Ratsmitglieder weiterhelfen kann.\n\nDie Suche wird sicher anstrengend, ist aber dringend notwendig, wenn wir den Rat neu aufbauen und die Brennende Legion besiegen wollen.", sourceObjective = "Interagiert mit den Schlachtplänen der Schreckensnarbe und schließt die Mission \"Durchsuchung des Archivs\" ab.", completion = "Bei der Durchsuchung des Archivs haben wir einen Folianten gefunden, der die Errichtung eines dämonischen Tors detailliert beschreibt. Damit hat man Zugriff auf alle Dämonenwelten, sofern man weiß, wohin man es richten muss.\n\nMithilfe eines solchen Tores könnten wir die verbleibenden Ratsmitglieder lokalisieren und retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42098] = { id = 42098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Eine herrenlose Seele", description = "Um den Anker zu erschaffen, müssen wir etwas von Shinfel an eine herrenlose Seele binden.\n\nDie Seele wird dadurch zu einem Leuchtfeuer, das Shinfel durch den Wirbelnden Nether und zurück zur Schreckensnarbe führen kann.\n\nShinfels Stab sollte uns die nötige Bindung ermöglichen, doch eine Seele zu finden, wird deutlich schwerer sein.\n\nTief in der Rabenwehr befindet sich ein Amalgam aus vielen Seelen. Einige von ihnen sind verloren und vergessen. Wenn Ihr diese Missgestalt tötet, erlangen wir sicher die benötigte Seele.", sourceObjective = "Besorgt eine herrenlose Seele vom Amalgam der Seelen in der Rabenwehr.", progress = "Habt Ihr die Seele schon gefunden?", completion = "Bei Euch wird man nie enttäuscht, {name}.\n\nDiese einst vergessene Seele wird nun einem wichtigen Zweck dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42100] = { id = 42100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ermächtigung der Seele", description = "Zur Erstellung des Ankers benötigen wir mehr Macht, als unsere Seelensplitter werden bieten können.\n\nDie Truppen von Schreckensnarbe sind in der Lage, riesige Mengen Seelensplitter anzusammeln, wenn sie unterwegs auf Missionen Feinde besiegen. Mit einer entsprechend großen Menge davon kann ich den Anker herstellen.", sourceObjective = "Sammelt mächtige Seelensplitter ein, indem Ihr Missionen der Ordenshalle abschließt.", progress = "Wenn wir genug Seelensplitter haben, haben wir auch genug Macht, um den Anker herzustellen.", completion = "Eure Truppen haben gute Arbeit geleistet. Mit diesem Vorrat an Seelensplittern sollten wir jetzt genug Macht für den Anker haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[42101] = { id = 42101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprache der Verlorenen" }
quests[42102] = { id = 42102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erweist Euch würdig", description = "Wenn wir die Schwestern erfolgreich herbeibeschwören wollen, brauchen wir die Hilfe eines Hexenmeisters, der sich mit der Beschwörung größerer Dämonen auskennt.\n\nWir können es uns nicht leisten, ein weiteres Ratsmitglied aufgrund mangelnder Erfahrung zu verlieren.\n\nAuf den Verheerten Inseln haben sich zahlreiche neue Hexenmeister eingefunden, die sich hier in dieser Zeit des Chaos einen Namen machen wollen.\n\nHoffentlich findet sich unter ihnen jemand, der dieses Rates würdig ist.", sourceObjective = "Interagiert mit der Späherkarte und schließt die Missionen der Reihe \"Erweist Euch würdig\" ab.", completion = "Unsere Suche zahlt sich jetzt hoffentlich aus. Ich habe von einem {class} gehört, der über die erforderlichen Fähigkeiten für das Beschwörungsritual verfügen könnte.\n\nWir sollten dem Hinweis so schnell wie möglich nachgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42103] = { id = 42103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahlzeit!", description = "Wir können mit dem Blutstein die Schwestern kontrollieren, sobald sie geschwächt sind, aber zunächst braucht er Nahrung.\n\nDie Macht des Steins wächst, wenn er das Blut von Dämonen verzehrt. Zu unserem Glück gibt es hier mehr als genug Dämonen, die wir zur Ader lassen können.", sourceObjective = "Tötet Dämonen überall auf den Verheerten Inseln und sammelt ihr Blut.", progress = "Wir müssen den Blutstein nähren, damit er stark genug wird, um die Eredarschwestern zu kontrollieren.", completion = "Das sollte mehr als genug Blut sein, um den Durst des Blutsteins zu stillen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42104] = { id = 42104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Unterkönig naht", description = "Ich bin zu lahm, um diese Nachzügler in Sicherheit zu bringen. Nehmt mein Horn und gebt das Signal für die Evakuierung.\n\nWir müssen alle hier wegbringen, bevor die Drogbar ankommen. Dann können die Kriegerhelden übernehmen.\n\nSchickt sie fürs Erste einfach zu Geistwandler Ebenhorn. Der Narr kann sich um sie kümmern, bis es wieder sicher ist.", sourceObjective = "Evakuiert die Flusswindung.", completion = "Der Unterkönig kommt. Haltet Eure Waffe lieber bereit, falls das hier kein gutes Ende nimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42105] = { id = 42105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixologiemischerei" }
quests[42106] = { id = 42106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeladener Gast" }
quests[42107] = { id = 42107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Fährte des großen Wurms", description = "Wir brauchen das Gjallarhorn, um die Armeen von Odyns Kindern zu sammeln. Und wenn der große Wurm es verschlungen hat, werden wir uns so lange durch die Erde graben, bis wir es in seinen Eingeweiden gefunden haben!", sourceObjective = "Schließt die Mission \"Auf der Fährte des großen Wurms\" ab.", completion = "Dann waren wir ruhmreich! Der große Wurm kann sich nicht vor uns verstecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[42108] = { id = 42108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Nachtwächter" }
quests[42110] = { id = 42110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gipfel!", description = "Eure Armeen haben die Bestie am höchsten Gipfel vom Hochberg ausfindig gemacht.\n\nSie kann nirgendwo mehr hinfliehen, wird aber von den widerwärtigen Drogbar beschützt. Ihr müsst Euch selbst dorthin begeben und Jorhuttam töten!", sourceObjective = "Begebt Euch zum Hochberggipfel.", completion = "Ihr seid hinter dem großen Wurm her? Ihr müsst entweder sehr tapfer oder sehr töricht sein.\n\nIch kenne jeden Winkel dieser Berge hier. Wenn Ihr mir helft, mein Dorf zu rächen, helfe ich Euch, dieses grässliche Monster zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[42111] = { id = 42111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Aufklärung" }
quests[42112] = { id = 42112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verdorrten kehren zurück" }
quests[42113] = { id = 42113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42114] = { id = 42114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ritual der Gezeiten", description = "Vor langer Zeit wurde der ersten Scharfseherin des Irdenen Rings eine Vision der Elemente gewährt.\n\nIn der Vision sah sie die Ankunft <eines neuen Scharfsehers voraus, der/einer neuen Scharfseherin voraus> die; uns durch eine schreckliche Zeit führen und die Elemente vereinen würde.\n\n{name}, ich glaube, dass Ihr <jener Scharfseher/jene Scharfseherin> aus der Prophezeiung seid und schon vor Eurer Geburt zu dieser Aufgabe berufen wart.\n\nDie Zeit ist gekommen, Euer Schicksal zu erfüllen!\n\nWenn Ihr bereit seid, werden wir das Ritual der Gezeiten ausführen und Neptulon herbeirufen, den ersten der vier großen Elementarlords.", sourceObjective = "Vollführt das Ritual der Gezeiten im Mahlstrom.", progress = "Die Zeit ist gekommen, um Euer Schicksal zu erfüllen, Scharfseher {name}.", completion = "Ich habe Euch bereits zuvor gesehen, Scharfseher.\n\n<Lord Neptulon schätzt Euch für einen Moment still ab, bevor er fortfährt.>\n\nIch sehe das Potenzial zu großer Macht in Euch. Wir werden sehen, ob die Prophezeiung wahr ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[42115] = { id = 42115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chapter 1 Completed" }
