quests[42119] = { id = 42119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein läuternder Cocktail" }
quests[42120] = { id = 42120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Silberne Hand", description = "Zu viele wissen jetzt, wo das Grabmal liegt. Es muss auf ewig verschlossen werden. Aber zuvor müssen wir den Hammer bergen.\n\nTyrosus hat uns eine Truppe von Streitern zugesprochen, die uns bei der Bergung des Hammers unterstützen soll, und einige aus meinem Orden werden uns dort ebenfalls treffen. Ich fürchte jedoch, dass selbst das nicht genug sein wird. Ich bin froh, dass Ihr bei uns sein werdet.\n\nNehmt das Portal zum Dalarankrater und fliegt dann nach Tirisfal, um dort zu uns zu stoßen. Ich habe den Ort auf Eurer Karte markiert.", sourceObjective = "Begebt Euch nach Tyrs Fall in Tirisfal und bergt die Silberne Hand.", completion = "Der erfolgreiche Abschluss Eurer Aufgabe erfüllt mich mit Mut. Wir haben Eure Rückkehr sehnlichst erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[42123] = { id = 42123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Llothien zurückerobern" }
quests[42124] = { id = 42124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexen und Verhexung" }
quests[42125] = { id = 42125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Flüstern", description = "Die Teufelsseelenbastion ist nicht weit weg, doch gut verteidigt. Sehr schwer, auf normalem Weg Zugang zu erhalten, doch Calydus kann Euch helfen, hineinzuschleichen!\n\nEs gibt ein Portal, das meine Art nutzt, um Schätze zu transportieren. Damit kommt Ihr hinein und könnt nach dem Schädel suchen.", sourceObjective = "Nutzt Calydus' Portal, um die Teufelsseelenbastion zu betreten und den Schädel der Man'ari zu holen.", completion = "Freund konnte den Schädel bekommen?\n\nJa, Calydus spürt ihn! Lasst ihn Calydus nicht ansehen, Freund. Ich arbeite gern ohne Zwang für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[42126] = { id = 42126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagierin Omniara", description = "Neben mir seht Ihr die Späherkarte. Über sie könnt Ihr unseren Verbündeten wichtige Missionen überall auf den Verheerten Inseln auftragen.\n\nDiese erste Aufgabe ist von entscheidender Bedeutung. Erzmagierin Omniara, eine berühmte Beschwörerin, war zur Halle des Wächters unterwegs, als sie angegriffen wurde.\n\nWir sollten Erzmagier Kalec entsenden, um ihr zu helfen. Er ist für diese Aufgabe wie geschaffen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Omniara braucht Hilfe\" ab.", completion = "Euer Champion hat gute Arbeit geleistet! Erzmagierin Omniara ist willens, sich uns anzuschließen, und macht sich schon bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[42127] = { id = 42127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau der Truppen", description = "Erzmagierin Omniara ist eine sehr mächtige Arkanistin und ihre Fertigkeiten werden unserem Orden eine große Hilfe sein.\n\nSie kann sogar mehrere Wasserelementare gleichzeitig beschwören! Glücklicherweise hat sie sich jetzt bereit erklärt, ihr Wissen mit uns zu teilen.\n\nSprecht bitte mit ihr und rekrutiert ihre Elementare.", sourceObjective = "Sprecht mit Erzmagierin Omniara und rekrutiert einige ihrer Wasserelementare.", completion = "Gute Arbeit. Diese Streitkräfte werden im Kampf gegen die Brennende Legion unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[42128] = { id = 42128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien des Rituals", description = "Der Schädel der Man'ari... eine gute Wahl! Er ist sehr mächtig und befindet sich im Besitz eines noch mächtigeren Schreckenslords.\n\nDoch es gibt auch eine Schwachstelle: Der Schädel hat einen eigenen Willen! Wenn wir mit dem Schädel kommunizieren würden, könnten wir ihn vielleicht überzeugen, lieber Euch zu dienen!\n\nWir brauchen Reagenzien aus der schwebenden Stadt, bevor wir mit dem Kommunikationsritual beginnen können. Staub von einem neuen Grab, dunkles Öl und einen mächtigen alkoholischen Katalysator.\n\nOh, und Blut! Ich spüre ein Tier, dessen Blut sich perfekt eignen würde.", sourceObjective = "Sucht innerhalb von Dalaran nach Grabstaub, einer Dose mit überhitztem Öl, einem gereiften Schneepflaumenbrandy und einer Hirschblutprobe.", progress = "Habt Ihr alles beschafft, Freund?", completion = "Sehr gut! Jetzt sind wir bereit, zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42129] = { id = 42129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sternenlichtanhänger", description = "Um meine Arbeit hier zu beenden, benötige ich einen magischen Gegenstand namens Sternenlichtanhänger.\n\nJahrhundertelang hatten die Erzdruiden des Hains der Träume diesen Anhänger von einem Bewahrer zum nächsten weitergereicht. Bis eines Tages eine Nagasirene eine List anwandte, um ihn an sich zu bringen!\n\nDieser Anhänger birgt eine große Menge arkaner Macht... Macht, die ich verwenden kann, um den Hain zu heilen.\n\nIch wäre Euch sehr dankbar, wenn Ihr ihn zurückholen könntet!", sourceObjective = "Besorgt den Sternenlichtanhänger von Abyssalkönigin Sha'rathra, die an der Küste Val'sharahs umherstreift.", progress = "Und? Ist viel Blut geflossen?", completion = "Ja, das ist er... der Anhänger der Bewahrer! Hurra! So macht Rache Spaß!", sourceObjectiveStatus = "unverified-source-field" }
quests[42130] = { id = 42130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbau der Truppen", sourceObjective = "Sprecht mit [Rekrutierer A], [Rekrutierer B] und [Rekrutierer C] und bildet neue Trupps aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[42131] = { id = 42131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwartete Besucher", description = "Aufgepasst, {name}. Ich spüre, dass sich eine seltsame Magie in der Kammer aufbaut. Irgendetwas nimmt dort Gestalt an.", sourceObjective = "Hört den unerwarteten Besuchern zu.", progress = "Caria und Varedis Teufelsseele sind wie Unkraut, das nie vergeht.", completion = "Diese beiden Marionetten von Kil'jaeden sind eine echte Plage. Ich bin froh, dass Ihr ihre Kriegsgleven habt.\n\nSo werden wir sie viel leichter töten können, wenn wir in ihre Welt eindringen.\n\nAber sagt, habt Ihr einen Moment Zeit, um eine dringende Angelegenheit zu besprechen?", sourceObjectiveStatus = "unverified-source-field" }
quests[42132] = { id = 42132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu guter Letzt", description = "Ich glaube, Ihr wisst bereits, was ich Euch mitteilen möchte... Ich denke, es ist an der Zeit, Allari und Jace als Eure Champions zu berufen.\n\nDie beiden haben bei der Planung und Vorbereitung der Invasion von Niskara eine bedeutende Rolle gespielt. Sie haben es sich verdient. Bessere Champions werdet Ihr nicht so einfach finden.", sourceObjective = "Rekrutiert Allari die Seelenfresserin und Jace Düsterweber als Eure Champions.", completion = "Jetzt gibt es nur noch eine Sache, um die wir uns kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42133] = { id = 42133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung am selben Tag", description = "Ich habe diese Waffen verzaubert, sodass sie jetzt den natürlichen Widerstand der Teufelshunde gegen Magie überwinden können. Zusätzlich sollte das Metall beim Aufprall ihre Schuppen zersplittern lassen und Euren Verbündeten so ermöglichen, den Dämonen noch mehr Schaden zuzufügen.\n\nIch glaube zwar nicht, dass die Verzauberungen im Laufe der Zeit nachlassen, aber trotzdem solltet Ihr die Waffen so schnell wie möglich ausliefern. Je länger sie hier sind, desto mehr Dämonen werden von ihrer Macht angezogen.", sourceObjective = "Kehrt zu Emmarel Schattenwächter in der Volltrefferhütte zurück.\n\nBereitgestellter Gegenstand:", completion = "Diese Waffen sind perfekt für den Kampf gegen Hakkar und seine Diener geeignet. Ich werde dafür sorgen, dass unsere Verbündeten sie erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[42134] = { id = 42134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung weiterer Truppen", description = "Unseren Champions ist es gelungen, den exzellenten Fährtenleser Sampson als Rekrutierer zu verpflichten.\n\nEr kann außergewöhnlich gut mit Tieren umgehen und lässt sich immer wieder von ihnen helfen. Und tatsächlich füllt er jetzt schon unsere Ställe mit Tieren, die er aufgespürt und gezähmt hat.\n\nSprecht jetzt mit ihm.", sourceObjective = "Sprecht mit Rekrutierer Sampson.", completion = "Es ist mir eine Ehre, dem Unsichtbaren Pfad zu dienen. Ich biete Euch jede erdenkliche Hilfe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[42135] = { id = 42135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy C" }
quests[42136] = { id = 42136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy A" }
quests[42137] = { id = 42137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Yalia Weisenwisper", sourceObjective = "Eure Hilfsbereitschaft ist bewundernswert. Zudem erhalte ich einen Eindruck davon, was für eine Art Anführer Ihr sein werdet.\n\nIch weiß, dass Ihr {class} aller Fraktionen zusammenbringen und gemeinsam gegen die Brennende Legion in den Kampf führen wollt. Das ist eine anspruchsvolle Aufgabe, aber Ihr seid dabei nicht allein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42138] = { id = 42138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Zabra Hexx", sourceObjective = "Ich hab bei Euch ein gutes Gefühl, {name}. Dieser fürchterliche Tag ist gleich etwas besser geworden, als Ihr aufgetaucht seid.\n\nMan könnte es für Glück halten, aber ich glaube, es ist Schicksal. Es war vorbestimmt, dass sich unsere Wege kreuzen.\n\nDies könnte der Anfang von etwas ganz Großem sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42139] = { id = 42139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Champions", description = "Die Ungekrönten arbeiten im Verborgenen, ziehen die Fäden oder trennen sie manchmal auch durch. Es ist eine Frage der richtigen Entscheidung im richtigen Augenblick und auf die denkbar eleganteste Art.\n\nWir alle haben entschieden, dass Ihr ein paar Schatten rekrutieren solltet, um sie auf die wichtigsten Missionen zu entsenden. Leute, denen Ihr vertrauen oder zumindest eine Aufgabe anvertrauen könnt.\n\nDürfte ich als Erstes gleich Garona und Vanessa vorschlagen? Das wäre zumindest in Anbetracht der jüngsten Ereignisse eine interessante Wahl.", sourceObjective = "Rekrutiert Garona die Halborcin und Vanessa van Cleef als Eure ersten Champions.", completion = "Dann werde ich hier also jede Menge Zeit mit Vanessa verbringen? Macht Euch mal keine Sorgen.\n\nSie und ich werden gut miteinander auskommen.\n\nSagt mal, habt Ihr einen kurzen Moment Zeit?", sourceObjectiveStatus = "unverified-source-field" }
quests[42140] = { id = 42140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein noch elenderer Hort des Abschaums und der Boshaftigkeit", description = "Ich habe gehört, dass Ihr jetzt die etwas, sagen wir mal, zwielichtigeren Typen rekrutiert?\n\nDann kenne ich genau die richtige Frau! Nein, nicht mich... Obwohl das wohl auch passen könnte. Auf jeden Fall aber gilt das für Lonika Stillstreich.\n\nJa, genau: DIE Lonika. Die Gründerin der \"Schule der Schurkenschaft\" in Shattrath.\n\nAlso, schickt Vanessa in die Scherbenwelt und lasst sie ihr ein Angebot machen, das sie nicht ablehnen kann. Oder besorgt ihr eine legale Arbeit und einen schöneren Ort für ihre Schurkenakademie.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Ein noch elenderer Hort des Abschaums und der Boshaftigkeit\" ab.", completion = "Sehr gut! Die Schurken, Diebe und Meuchelmörder trudeln langsam ein.\n\n<Nikki schaut zu Vanessa herüber und flüstert Euch zu.>\n\nVielleicht können wir sogar ein paar arbeitslose Defias überzeugen. Oder ist das noch zu früh?", sourceObjectiveStatus = "unverified-source-field" }
quests[42141] = { id = 42141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörer Morn", description = "Da wir nun Champions für unseren Orden gewonnen haben, können wir die Späherkarte nutzen, um wichtige Aufträge auf den Verheerten Inseln abzuschließen.\n\nUnser erster Auftrag ist absolut entscheidend. Beschwörer Morn, ein Meister der Elementare, war auf dem Weg zum Herz von Azeroth, als er angegriffen wurde.\n\nWir sollten Sturmruferin Mylra entsenden, um ihm zu helfen. Sie ist für diese Aufgabe wie geschaffen.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Morn braucht Hilfe\" ab.", completion = "Gut, Mylras Mission war ein voller Erfolg! Unsere Rekrutierungsbemühungen haben sich ausgezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[42142] = { id = 42142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutierung der Truppen", description = "Unsere Champions haben die Talente von Beschwörer Morn, einem mächtigen Schamanen, für uns gewonnen.\n\nEr ist für seine enge Verbundenheit mit der Erde bekannt und passt wunderbar in unseren Orden. Er ist schon dabei, geringe Elementare für uns anzuwerben.\n\nSprecht mit ihm und bildete einen geringen Elementar aus.", sourceObjective = "Sprecht mit Beschwörer Morn und beschwört einen geringen Elementar.", completion = "Ausgezeichnet. Diese Trupps werden bei der Verteidigung der Verheerten Inseln unschätzbare Dienste leisten. Ihr könnt sie genauso auf Missionen schicken wie die Champions.", sourceObjectiveStatus = "unverified-source-field" }
quests[42143] = { id = 42143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berufung des Champions [WIP]" }
