quests[42146] = { id = 42146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betäubt und verwirrt und goldig" }
quests[42147] = { id = 42147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erstkontakt", description = "Es wird Zeit, Eure neue Verkleidung zu testen.\n\nEuer erster Kontakt ist Vanthir, ein Händler aus dem Arbeiterviertel. Er besucht heute einen seiner Zulieferer auf der Großen Promenade.\n\nSagt Vanthir, dass er mich wegen einer Ladung Dämmerlilienknollen aufsuchen soll. Er wird schon verstehen.\n\nIm Abschluss müssen wir uns weiter vorbereiten. Ihr solltet in der Zwischenzeit zu Thalyssra zurück.\n\n<Ly'leth händigt Euch eine verkorkte Flasche mit einer schwach leuchtenden Flüssigkeit aus.>\n\nBestellt ihr meine Grüße und gebt ihr dies hier. Wir werden uns bald bei Euch melden.", sourceObjective = "Sprecht mit Vanthir auf der Großen Promenade.", progress = "Habt Ihr schon Kontakt zu unseren Unterstützern aufgenommen?", completion = "Die Familie Lunastre verfügt über beste Beziehungen. Sie werden uns zu gegebener Zeit eine große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[42148] = { id = 42148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wein ist schlecht" }
quests[42149] = { id = 42149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen, das man nicht teilen sollte", description = "Mir ist nicht entgangen, dass einige der Bücher der Empyreumgesellschaft mit Teufelsmagie verzaubert sind. Das ist Blasphemie! Wir sollten so viele davon konfiszieren wie möglich.", sourceObjective = "Sammelt 5 Dämonenfolianten der Empyreumgesellschaft ein.", progress = "Ich hoffe, dass wir alle Bücher gefunden haben.", completion = "Bringt sie besser zur sicheren Verwahrung zurück in die Halle des Wächters, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[42150] = { id = 42150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übergriff der Naga von Kal'delar" }
