quests[42154] = { id = 42154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helft einem Welpen" }
quests[42158] = { id = 42158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Werkstatt des Schöpfers", description = "Mein ferngesteuertes Beobachtungsrelais hat in diesem Grab eine erstaunliche Menge an Daten gesammelt.\n\nWenn wir die gespeicherten Daten in meine Kernverarbeitungssysteme herunterladen können, sollte ich in der Lage sein, Titanenblitz zu lokalisieren... und diese widerwärtige Vrykuldame, die das Artefakt gestohlen hat.\n\nDa Ihr schon hier seid, würde es Euch etwas ausmachen, mir behilflich zu sein? Die Verarbeitung dieser Informationen überlädt womöglich einige meiner Ausfallsicherungen und ich weiß, dass Ihr <einer/eine> von der fähigen Sorte seid!", sourceObjective = "Unterstützt Mimiron.", progress = "Denkt dran, alles ist Wissenschaft, wenn man es aufschreibt!", completion = "Der Tempel der Stürme ist ganz in der Nähe. Ihr müsstet also vor dieser diebischen Vrykul dort eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[42159] = { id = 42159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training mit den Nachtwächtern" }
